/* Fiches d'exécution détaillées : position de départ (d), étapes (e),
   points de vigilance (v), respiration (r). EXERCISE_DESC sert de repli
   court quand un exercice n'a pas encore de fiche complète. */

export const EXERCISE_GUIDE = {
  j1:{d:"Debout, pieds écartés de la largeur des épaules, pointes légèrement ouvertes vers l'extérieur. Bras tendus devant toi ou croisés sur la poitrine.",e:["Inspire et bascule d'abord le bassin vers l'arrière, comme pour aller chercher une chaise derrière toi. C'est la hanche qui initie le mouvement, pas le genou.","Fléchis les genoux en descendant, en gardant le buste incliné mais le dos parfaitement droit.","Descends jusqu'à ce que les cuisses soient parallèles au sol, ou moins bas si ta mobilité ne le permet pas encore.","Marque un temps d'arrêt d'une demi-seconde en bas, sans rebondir.","Remonte en poussant dans les talons et en serrant les fessiers en fin de mouvement."],v:["Les genoux ne doivent pas rentrer vers l'intérieur : pousse-les activement vers l'extérieur.","Les talons restent au sol du début à la fin ; s'ils se décollent, réduis l'amplitude.","Le dos ne s'arrondit jamais, même en bas."],r:"Inspire à la descente, souffle à la remontée."},
  j2:{d:"Debout, pieds serrés, mains sur les hanches pour la stabilité.",e:["Fais un grand pas en avant, d'environ un mètre selon ta taille.","Descends verticalement en fléchissant les deux genoux simultanément, jusqu'à ce qu'ils forment chacun un angle proche de 90°.","Le genou arrière descend vers le sol sans le toucher, le genou avant reste au-dessus de la cheville.","Pousse dans le talon avant pour revenir à la position debout.","Alterne la jambe à chaque répétition, ou termine toutes les répétitions d'un côté avant de changer."],v:["Le genou avant ne dépasse jamais la pointe du pied : si c'est le cas, ton pas était trop court.","Le buste reste vertical, ne te penche pas en avant.","Fixe un point devant toi : regarder le sol déséquilibre."],r:"Inspire en descendant, souffle en repoussant."},
  j3:{d:"Pied arrière posé sur une chaise ou un banc stable, pied avant à environ un grand pas devant, bassin bien de face.",e:["Vérifie ta position avant de commencer : en descendant, ton genou avant doit rester au-dessus de la cheville.","Descends verticalement en fléchissant la jambe avant, comme si un ascenseur te faisait descendre.","Va jusqu'à ce que la cuisse avant soit parallèle au sol, ou moins bas au début.","Pousse dans le talon avant pour remonter, sans t'aider de la jambe arrière.","Effectue toutes les répétitions d'un côté avant de changer de jambe."],v:["La jambe arrière ne sert qu'à l'équilibre : tout le travail est porté par la jambe avant.","Si tu tangues, rapproche légèrement le pied avant ou tiens-toi d'une main à un mur.","Ne laisse pas le bassin tourner sur le côté."],r:"Inspire à la descente, souffle à la remontée."},
  j4:{d:"Debout, pieds écartés de la largeur des épaules, un poids ou un objet lourd tenu à deux mains contre la poitrine, coudes vers le bas.",e:["Serre le poids contre le sternum : le contrepoids devant t'aide à garder le buste droit.","Bascule le bassin vers l'arrière et descends en fléchissant les genoux.","La charge devant permet de descendre plus bas qu'un squat classique tout en gardant le dos droit.","Descends jusqu'à ce que les coudes touchent presque l'intérieur des cuisses.","Remonte en poussant dans les talons, en gardant le poids collé à la poitrine."],v:["Ne laisse pas les coudes s'écarter : le poids glisserait vers l'avant et déséquilibrerait.","Garde la poitrine ouverte et les épaules en arrière.","Les talons restent ancrés au sol."],r:"Inspire à la descente, souffle à la remontée."},
  j5:{d:"Debout dans un espace dégagé d'au moins cinq mètres, mains sur les hanches.",e:["Fais un grand pas en avant et descends en fente jusqu'à ce que les deux genoux soient proches de 90°.","Au lieu de revenir en arrière, pousse dans le talon avant pour te propulser vers l'avant.","Ramène la jambe arrière vers l'avant et enchaîne directement la fente suivante.","Progresse ainsi en avançant, en alternant naturellement les jambes.","Fais demi-tour et reviens quand tu manques d'espace."],v:["Ne te penche pas en avant lors de la propulsion : c'est le talon avant qui pousse, pas le buste.","Garde une cadence lente et contrôlée, l'exercice n'est pas une marche rapide.","Le genou arrière ne touche jamais le sol."],r:"Souffle à chaque poussée vers l'avant."},
  j6:{d:"Debout, pieds écartés de la largeur des hanches, genoux très légèrement déverrouillés, mains posées devant les cuisses.",e:["Bascule le bassin vers l'arrière et incline le buste vers l'avant en faisant glisser tes mains le long des cuisses.","Les genoux restent quasiment fixes : le mouvement vient uniquement de la hanche.","Descends jusqu'à sentir un étirement franc à l'arrière des cuisses, généralement vers le milieu du tibia.","Arrête-toi dès que le bas du dos commence à s'arrondir : c'est ta limite d'amplitude du jour.","Remonte en contractant les fessiers et en poussant le bassin vers l'avant."],v:["Ce n'est pas un squat : les genoux ne se fléchissent presque pas.","Le dos doit rester droit du bassin à la nuque, jamais arrondi.","Ne cherche pas à toucher le sol, l'amplitude dépend de ta souplesse."],r:"Inspire en descendant, souffle en remontant."},
  j7:{d:"Debout au centre d'un élastique, une extrémité dans chaque main, mains au niveau des épaules, coudes fléchis.",e:["Vérifie que l'élastique est bien tendu en position haute avant de commencer.","Descends en squat en gardant les mains fixes au niveau des épaules.","L'élastique se tend davantage à mesure que tu remontes : la résistance augmente là où tu es le plus fort.","Descends jusqu'à ce que les cuisses soient parallèles au sol.","Remonte en poussant dans les talons, en résistant à la traction de l'élastique."],v:["Ne laisse pas les mains descendre : elles restent ancrées aux épaules.","Les genoux poussent vers l'extérieur, l'élastique tend à les faire rentrer.","Vérifie l'état de l'élastique avant chaque séance."],r:"Inspire à la descente, souffle à la remontée."},
  j8:{d:"Assis dans la machine, dos et bassin bien plaqués contre le dossier, pieds à plat sur le plateau, écartés de la largeur des hanches.",e:["Règle le siège pour que tes genoux forment un angle d'environ 90° au départ, pas plus fermé.","Pousse le plateau en tendant les jambes, sans jamais verrouiller complètement les genoux.","Marque une brève pause en position tendue, sans bloquer.","Reviens lentement en contrôlant la descente, jusqu'à retrouver l'angle de départ.","Enchaîne sans laisser la charge reposer entre les répétitions."],v:["Ne verrouille jamais les genoux en extension : l'articulation encaisserait toute la charge.","Le bas du dos reste collé au dossier ; s'il se décolle, la charge est trop lourde ou l'amplitude trop grande.","Les talons ne se décollent pas du plateau."],r:"Souffle en poussant, inspire au retour."},
  j9:{d:"Assis dans la machine, dos contre le dossier, chevilles derrière le rouleau, genoux alignés avec l'axe de rotation.",e:["Règle le rouleau pour qu'il repose juste au-dessus des chevilles, pas sur le tibia.","Tends les jambes en montant le rouleau, jusqu'à l'extension complète.","Marque une contraction d'une seconde en haut, cuisses fermement serrées.","Redescends lentement en comptant deux à trois secondes : c'est la phase la plus efficace.","Arrête-toi avant que la charge ne repose entièrement, puis enchaîne."],v:["Ne donne pas d'élan avec le buste : seules les jambes travaillent.","Garde les mains sur les poignées latérales pour stabiliser le bassin.","Ne descends pas trop vite : le relâchement brutal met le genou en tension."],r:"Souffle en tendant, inspire en redescendant."},
  j10:{d:"Allongé sur le ventre dans la machine, rouleau posé juste au-dessus des talons, bassin bien plaqué.",e:["Vérifie que le rouleau est au-dessus du talon d'Achille et non sur le mollet.","Fléchis les genoux en amenant les talons vers les fessiers.","Monte jusqu'à la contraction maximale, sans que le bassin ne se décolle.","Marque une pause d'une seconde en position haute.","Redescends lentement en contrôlant, sans laisser la charge tomber."],v:["Le bassin ne doit pas se soulever : s'il se décolle, la charge est trop lourde.","Ne fais pas de mouvement de bascule avec le bas du dos.","Garde les pointes de pieds relâchées pour ne pas déclencher de crampe."],r:"Souffle en fléchissant, inspire en redescendant."},
  j11:{d:"Debout, pieds nettement plus larges que les épaules, pointes ouvertes à environ 45° vers l'extérieur.",e:["Vérifie l'orientation des pieds : les genoux doivent suivre exactement l'axe des pointes.","Descends verticalement en poussant activement les genoux vers l'extérieur.","Le buste reste plus droit que dans un squat classique, l'écartement des pieds le permettant.","Descends jusqu'à ce que les cuisses soient parallèles au sol.","Remonte en poussant dans les talons et en serrant l'intérieur des cuisses."],v:["Si les genoux rentrent vers l'intérieur, réduis l'écartement des pieds.","Les talons restent au sol ; s'ils se décollent, tes pointes sont trop ouvertes.","Ne cambre pas le bas du dos en position basse."],r:"Inspire à la descente, souffle à la remontée."},
  j12:{d:"Debout, pieds écartés de la largeur des épaules, bras le long du corps, genoux souples.",e:["Descends en squat jusqu'à mi-hauteur, plus haut qu'un squat classique pour préparer l'impulsion.","Détends-toi vers le haut en poussant explosivement dans les jambes, bras vers l'arrière puis vers le haut.","Décolle franchement du sol, sans chercher la hauteur maximale au début.","Amortis la réception sur la pointe des pieds puis déroule vers les talons, genoux souples.","Enchaîne directement le squat suivant sans temps mort."],v:["Ne jamais retomber jambes tendues : l'amortissement se fait genoux fléchis.","Si tu entends un bruit sourd à la réception, tu amortis mal.","Arrête la série dès que la qualité de réception se dégrade."],r:"Souffle à l'impulsion, inspire pendant la descente suivante."},
  j13:{d:"Adosse-toi à un mur, pieds écartés de la largeur des hanches et avancés d'environ un demi-mètre.",e:["Fais glisser ton dos le long du mur en descendant progressivement.","Arrête-toi quand tes cuisses sont parallèles au sol et tes genoux à 90°.","Vérifie que tes genoux sont exactement au-dessus des chevilles : ajuste la position des pieds si nécessaire.","Plaque tout le dos contre le mur, du bassin aux omoplates, et laisse les bras le long du corps.","Tiens la position immobile pendant toute la durée prévue."],v:["Ne prends pas appui sur tes cuisses avec les mains, cela allège l'exercice de moitié.","Le bas du dos ne doit pas se décoller du mur.","Si les genoux dépassent les pointes de pieds, avance davantage les pieds."],r:"Respire normalement et sans blocage : c'est un maintien, pas un effort en apnée."},
  j14:{d:"Debout, pieds serrés, mains sur les hanches ou devant la poitrine.",e:["Fais un grand pas sur le côté, en gardant les deux pointes de pieds dirigées vers l'avant.","Fléchis la jambe du côté du pas en poussant les fesses vers l'arrière, comme un squat sur une jambe.","L'autre jambe reste tendue, tu dois sentir l'étirement de l'intérieur de la cuisse.","Le buste s'incline légèrement vers l'avant, dos droit.","Repousse sur la jambe fléchie pour revenir au centre, puis alterne."],v:["La jambe tendue ne se plie pas : elle donne le repère d'amplitude.","Le genou fléchi reste dans l'axe du pied, il ne rentre pas vers l'intérieur.","Ne laisse pas le dos s'arrondir en descendant."],r:"Inspire en écartant, souffle en revenant."},
  j15:{d:"Debout, pieds serrés, mains sur les hanches.",e:["Fais un grand pas en arrière, en posant la pointe du pied en premier.","Descends verticalement jusqu'à ce que le genou arrière approche le sol.","Le genou avant reste au-dessus de la cheville, à 90°.","Pousse dans le talon avant pour ramener la jambe arrière et revenir debout.","Alterne les jambes à chaque répétition."],v:["Cette version ménage davantage le genou avant que la fente avant : privilégie-la si tu ressens une gêne.","Ne pose pas le talon arrière au sol, seule la pointe touche.","Le buste reste vertical."],r:"Inspire en reculant, souffle en revenant."},
  j16:{d:"Pied arrière posé sur une chaise basse ou une marche, pied avant à un grand pas devant, mains sur les hanches.",e:["Commence avec une surélévation basse, une marche suffit : plus elle est haute, plus l'exercice est exigeant.","Descends verticalement en fléchissant la jambe avant.","Va jusqu'à ce que la cuisse avant approche la parallèle au sol.","Pousse dans le talon avant pour remonter.","Termine toutes les répétitions d'un côté avant de changer."],v:["Ne pousse pas avec la jambe arrière, elle ne sert qu'à l'équilibre.","Si tu perds l'équilibre, tiens-toi d'une main à un mur ou à une chaise.","Le bassin reste de face, sans rotation."],r:"Inspire à la descente, souffle à la remontée."},
  j17:{d:"Face à une chaise stable ou une marche haute, un pied entièrement posé dessus.",e:["Vérifie la stabilité du support avant de monter dessus.","Pose tout le pied sur le support, pas seulement la pointe.","Pousse dans le talon du pied surélevé pour monter, jusqu'à tendre complètement la jambe.","Ne t'aide pas d'une impulsion du pied resté au sol : c'est la jambe du haut qui fait tout le travail.","Redescends lentement en contrôlant, en posant la pointe puis le talon."],v:["Si tu prends appui avec la jambe du bas, baisse le support.","Le buste reste droit, sans se pencher vers l'avant.","Le genou de la jambe qui pousse suit l'axe du pied."],r:"Souffle en montant, inspire en redescendant."},
  j18:{d:"Debout à côté d'une poignée de porte, d'un montant ou d'une chaise, une main en appui léger.",e:["Tends une jambe devant toi, à quelques centimètres du sol.","Descends lentement sur la jambe d'appui, en te servant du support uniquement pour l'équilibre.","Descends aussi bas que ton contrôle le permet, sans t'effondrer sur la fin.","Marque une brève pause en bas.","Remonte en poussant dans le talon, sans tirer sur le support."],v:["Utilise le support autant que nécessaire au début : mieux vaut s'aider qu'exécuter un mouvement chaotique.","Le talon d'appui reste au sol pendant toute la descente.","Ne laisse pas le genou rentrer vers l'intérieur."],r:"Inspire en descendant, souffle en remontant."},
  j19:{d:"Debout, pieds écartés de la largeur des hanches, éventuellement l'avant des pieds sur une marche pour gagner en amplitude.",e:["Monte lentement sur la pointe des pieds, le plus haut possible.","Marque une contraction franche d'une seconde en position haute, mollets serrés.","Redescends lentement en trois secondes, sans laisser tomber le talon.","Si tu utilises une marche, laisse le talon descendre sous le niveau de la marche pour étirer.","Enchaîne sans marquer de pause en bas."],v:["La lenteur est essentielle : monter et descendre en rebondissant ne produit presque aucun effet.","Garde les genoux tendus mais non verrouillés.","Tiens-toi à un mur si l'équilibre est instable, sans t'y appuyer."],r:"Souffle en montant, inspire en redescendant."},
  j20:{d:"Debout, pieds écartés de la largeur des hanches, mains posées derrière la tête ou croisées sur la poitrine, genoux très légèrement fléchis.",e:["Bascule le bassin vers l'arrière et incline le buste vers l'avant.","Garde le dos parfaitement droit, comme une planche qui pivote à la hanche.","Descends jusqu'à ce que le buste approche l'horizontale, ou moins bas selon ta souplesse.","Arrête-toi dès que le bas du dos commence à s'arrondir.","Remonte en contractant les fessiers, sans cambrer en fin de mouvement."],v:["Le bas du dos ne doit jamais s'arrondir : c'est la limite absolue de l'amplitude.","Ne cambre pas en position haute, arrête-toi à l'alignement.","Commence avec les mains sur la poitrine, la position derrière la tête étant plus exigeante."],r:"Inspire en descendant, souffle en remontant."},
  f1:{d:"Allongé sur le dos, genoux fléchis, pieds à plat au sol écartés de la largeur des hanches, talons à environ vingt centimètres des fesses. Bras le long du corps.",e:["Plaque le bas du dos au sol et rentre légèrement le bassin avant de commencer.","Pousse dans les talons pour décoller le bassin du sol.","Monte jusqu'à aligner épaules, hanches et genoux, sans aller plus haut.","Serre fort les fessiers en position haute pendant une seconde complète.","Redescends lentement sans poser complètement le bassin, puis enchaîne."],v:["Ne cherche pas à monter plus haut que l'alignement : tu cambrerais le bas du dos au lieu de solliciter les fessiers.","Si tu sens l'arrière des cuisses travailler plus que les fessiers, rapproche les talons.","Les genoux restent écartés de la largeur des hanches, ils ne se rapprochent pas."],r:"Souffle en montant, inspire en redescendant."},
  f2:{d:"Allongé sur le dos, genoux fléchis, un élastique passé autour du bassin et maintenu au sol par les mains de chaque côté.",e:["Vérifie que l'élastique est bien centré sur le bassin et non sur les côtes.","Pousse dans les talons pour décoller le bassin, contre la résistance de l'élastique.","Monte jusqu'à l'alignement épaules-hanches-genoux.","L'élastique se tend au maximum en position haute, exactement là où le fessier est le plus contracté.","Serre une seconde puis redescends lentement en résistant."],v:["Maintiens fermement l'élastique au sol : s'il glisse, il remonte le long du corps.","Ne cambre pas le bas du dos pour compenser la résistance.","Vérifie l'état de l'élastique avant chaque séance."],r:"Souffle en montant, inspire en redescendant."},
  f3:{d:"Assis au sol, haut du dos appuyé contre un canapé ou un banc, genoux fléchis, pieds à plat, un poids posé sur le bassin.",e:["Tiens le poids à deux mains pour qu'il ne glisse pas pendant le mouvement.","Cale les omoplates contre le support, le bassin en suspension.","Pousse dans les talons pour monter le bassin jusqu'à ce que le buste soit horizontal.","Rentre légèrement le menton et serre les fessiers une seconde en haut.","Redescends jusqu'à ce que le bassin approche le sol, sans le poser."],v:["L'amplitude est bien plus grande qu'au pont fessier classique : va progressivement.","Ne cambre pas le bas du dos en position haute, cherche l'horizontale du buste.","Place un coussin sous le poids pour éviter les points de pression."],r:"Souffle en montant, inspire en redescendant."},
  f4:{d:"À quatre pattes, mains sous les épaules, genoux sous les hanches, dos plat.",e:["Contracte le ventre pour verrouiller le bassin avant de commencer.","Monte une jambe vers l'arrière et le haut en gardant le genou fléchi à 90°.","Imagine que tu pousses le plafond avec la plante du pied.","Monte jusqu'à ce que la cuisse soit dans le prolongement du buste, sans aller plus haut.","Redescends sans poser le genou au sol, puis enchaîne."],v:["Ne creuse pas le bas du dos pour monter plus haut : c'est le défaut le plus courant.","Le bassin reste face au sol, il ne bascule pas sur le côté.","Passe sur les avant-bras si tes poignets sont sensibles."],r:"Souffle en montant, inspire en redescendant."},
  f5:{d:"Assis dans la machine, dos contre le dossier, coussins latéraux contre l'extérieur des cuisses.",e:["Règle l'écartement de départ pour que les genoux soient légèrement rapprochés, sans forcer.","Écarte les cuisses en poussant contre les coussins, jusqu'à l'amplitude maximale confortable.","Marque une contraction d'une seconde en position ouverte.","Reviens lentement en résistant, sans laisser la charge revenir d'un coup.","Arrête-toi avant le contact complet des coussins, puis enchaîne."],v:["Ne te penche pas en avant pour gagner en amplitude : le dos reste au dossier.","Le retour contrôlé compte autant que l'ouverture.","Garde les pieds à plat sur les repose-pieds."],r:"Souffle en écartant, inspire au retour."},
  f6:{d:"Debout, pieds serrés, mains sur les hanches, dans un espace dégagé.",e:["Fais un grand pas en arrière et descends en fente, genou arrière proche du sol.","Depuis cette position basse, pousse explosivement dans les deux jambes pour décoller.","Change de jambe en l'air, sans à-coup du buste.","Retombe directement en fente de l'autre côté, en amortissant genoux souples.","Enchaîne en alternant, sans temps mort."],v:["Exercice exigeant en coordination : maîtrise la fente arrière classique avant de l'aborder.","Amortis toujours la réception, ne retombe jamais jambes raides.","Arrête la série dès que la réception devient bruyante ou instable."],r:"Souffle à l'impulsion, inspire pendant la descente."},
  f7:{d:"Allongé sur le dos, un pied à plat au sol genou fléchi, l'autre jambe tendue vers le plafond.",e:["Plaque le bas du dos au sol et contracte le ventre pour stabiliser le bassin.","Pousse dans le talon au sol pour décoller le bassin.","Monte jusqu'à aligner épaules, hanche et genou de la jambe d'appui.","Vérifie que le bassin reste horizontal : il a naturellement tendance à s'affaisser du côté de la jambe levée.","Serre le fessier une seconde puis redescends sans poser complètement."],v:["Si le bassin bascule d'un côté, l'exercice perd tout son intérêt : réduis l'amplitude ou reviens à la version à deux jambes.","La jambe levée reste tendue et immobile, elle ne donne pas d'élan.","Ne cambre pas le bas du dos en position haute."],r:"Souffle en montant, inspire en redescendant."},
  f8:{d:"À quatre pattes, avant-bras posés au sol pour soulager les poignets, genoux sous les hanches.",e:["Contracte le ventre pour verrouiller le bassin.","Tends une jambe vers l'arrière en gardant le genou légèrement fléchi.","Monte jusqu'à ce que la cuisse soit dans le prolongement du buste.","Serre le fessier une seconde en position haute.","Redescends lentement sans poser le genou, puis enchaîne."],v:["La position sur les avant-bras est plus stable que sur les mains : privilégie-la si tu débutes.","Ne creuse jamais le bas du dos pour gagner en hauteur.","Le bassin reste face au sol."],r:"Souffle en tendant la jambe, inspire au retour."},
  f9:{d:"À quatre pattes, mains sous les épaules, genoux sous les hanches, genou fléchi à 90°.",e:["Contracte le ventre et fixe le bassin bien face au sol.","Ouvre une jambe sur le côté en gardant le genou plié.","Monte jusqu'à hauteur de hanche, pas plus haut.","Le bassin ne doit pas basculer pour accompagner le mouvement : c'est le point clé.","Redescends lentement sans poser le genou."],v:["Si le corps s'incline du côté opposé, tu compenses : réduis l'amplitude.","Ce mouvement cible le moyen fessier, sur le côté de la hanche, pas le grand fessier.","L'amplitude est naturellement faible, ne cherche pas à l'augmenter."],r:"Souffle en ouvrant, inspire en refermant."},
  f10:{d:"Installe-toi en pont fessier, bassin décollé et bien haut, épaules-hanches-genoux alignés.",e:["Stabilise d'abord la position haute pendant deux ou trois secondes.","Sans laisser le bassin redescendre, avance un pied de quelques centimètres seulement.","Avance ensuite l'autre pied de la même distance.","Fais deux ou trois pas ainsi, puis reviens en reculant les pieds un par un.","Redescends le bassin seulement à la fin de la série."],v:["Le maintien du bassin est plus difficile que le déplacement : si le bassin s'affaisse, arrête-toi.","Le bassin ne doit pas non plus tourner d'un côté à l'autre.","Fais de très petits pas, quelques centimètres suffisent."],r:"Respire régulièrement et sans blocage pendant tout le déplacement."},
  f11:{d:"Debout, pieds serrés, mains sur les hanches.",e:["Fais un grand pas en arrière en croisant la jambe derrière l'autre, en diagonale.","Descends en fléchissant les deux genoux, buste droit.","Le croisement met le moyen fessier de la jambe avant en tension.","Descends aussi bas que ton équilibre le permet.","Repousse sur la jambe avant pour revenir, puis alterne."],v:["Mouvement exigeant en coordination et en mobilité de hanche : va progressivement.","Le genou avant reste dans l'axe du pied, il ne rentre pas.","Si tu tangues, réduis l'amplitude du croisement."],r:"Inspire en croisant, souffle en revenant."},
  f12:{d:"Allongé sur le côté, jambes tendues et superposées, tête posée sur le bras du dessous, hanches empilées.",e:["Aligne épaules, bassin et chevilles : le corps doit former une ligne droite.","Pose la main du dessus au sol devant toi pour stabiliser.","Monte la jambe du dessus le plus haut possible sans basculer le bassin vers l'arrière.","Garde la pointe de pied dirigée vers l'avant, jamais vers le plafond.","Redescends lentement sans poser complètement la jambe."],v:["La bascule du bassin vers l'arrière est le défaut principal : elle transfère le travail sur d'autres muscles.","Si tu montes très haut, tu compenses probablement : l'amplitude utile est modeste.","La pointe de pied tournée vers le plafond sollicite le quadriceps au lieu du fessier."],r:"Souffle en montant, inspire en redescendant."},
  f13:{d:"Allongé sur le dos, talons posés sur une chaise ou un canapé, genoux fléchis à 90°, bras le long du corps.",e:["Vérifie la stabilité du support avant de commencer.","Plaque le bas du dos au sol et contracte le ventre.","Pousse dans les talons pour décoller le bassin.","Monte jusqu'à aligner épaules, hanches et genoux : la surélévation augmente l'amplitude par rapport au pont classique.","Serre les fessiers une seconde puis redescends sans poser."],v:["Ne pousse pas le support en arrière : garde une pression verticale dans les talons.","L'amplitude accrue rend la cambrure plus tentante : arrête-toi à l'alignement.","Si le support glisse, cale-le contre un mur."],r:"Souffle en montant, inspire en redescendant."},
  f14:{d:"Prends la position du squat sumo, pieds larges et pointes ouvertes, et descends jusqu'à ce que les cuisses soient parallèles au sol.",e:["Reste en position basse pendant toute la série, sans jamais te redresser.","Effectue de petites remontées de quelques centimètres seulement.","Redescends immédiatement à la position basse.","Garde une cadence régulière et contrôlée, sans rebondir.","Le fessier reste sous tension continue du début à la fin de la série."],v:["Ne te redresse pas complètement, cela relâcherait la tension et annulerait l'intérêt de l'exercice.","Les genoux poussent activement vers l'extérieur pendant tout le mouvement.","Le dos reste droit malgré la fatigue accumulée."],r:"Respire régulièrement, sans bloquer, la position basse étant maintenue longtemps."},
  f15:{d:"Debout face à un mur, mains en appui à hauteur de poitrine, buste droit.",e:["Contracte le ventre pour éviter de cambrer.","Tends une jambe vers l'arrière, genou tendu, jusqu'à sentir la contraction du fessier.","L'amplitude utile est faible : arrête-toi dès que le bassin veut basculer.","Marque une contraction d'une seconde en position haute.","Redescends lentement sans poser complètement le pied."],v:["Ne cambre pas le bas du dos pour monter plus haut, c'est le défaut le plus fréquent.","Le buste reste vertical, ne te penche pas vers le mur.","Le bassin reste de face."],r:"Souffle en tendant la jambe, inspire au retour."},
  f16:{d:"Allongé sur le côté, genoux fléchis à environ 45°, pieds superposés, hanches empilées.",e:["Aligne épaules et bassin, et pose la main du dessus au sol devant toi.","Sans décoller les pieds l'un de l'autre, ouvre le genou du dessus vers le plafond.","Le bassin ne bascule pas vers l'arrière : c'est la condition pour que le moyen fessier travaille.","Marque une pause en position ouverte.","Referme lentement sans relâcher complètement."],v:["L'amplitude est très faible, quelques centimètres suffisent : chercher plus signifie compenser.","Les pieds restent collés l'un à l'autre pendant tout le mouvement.","Si tu ne sens rien, vérifie que le bassin ne recule pas."],r:"Souffle en ouvrant, inspire en refermant."},
  f17:{d:"Allongé sur le dos, plante des pieds appuyée contre un mur, genoux fléchis à 90°, bras le long du corps.",e:["Recule ou avance légèrement pour que tes genoux forment bien un angle droit.","Plaque le bas du dos au sol et contracte le ventre.","Pousse dans les pieds contre le mur pour décoller le bassin.","Le mur stabilise entièrement l'appui : tu peux te concentrer uniquement sur la contraction du fessier.","Serre une seconde en haut puis redescends sans poser complètement."],v:["Ne pousse pas si fort que tu glisses en arrière : la pression est ferme mais mesurée.","Arrête-toi à l'alignement épaules-hanches-genoux, sans cambrer.","Version idéale pour apprendre le geste avant de passer au pont classique."],r:"Souffle en montant, inspire en redescendant."},
  f18:{d:"À quatre pattes, avant-bras posés au sol, genoux sous les hanches, dos plat.",e:["Contracte le ventre pour verrouiller le bassin avant de bouger.","Tends une jambe vers l'arrière en gardant le genou légèrement fléchi.","Monte jusqu'à ce que la cuisse soit dans le prolongement du buste.","La position sur les avant-bras est plus stable que sur les mains et soulage les poignets.","Redescends lentement sans poser le genou au sol."],v:["Ne creuse jamais le bas du dos : si tu ne peux pas monter sans cambrer, monte moins haut.","Le bassin reste face au sol, sans rotation.","Le mouvement est lent et contrôlé, sans élan."],r:"Souffle en tendant la jambe, inspire au retour."},
  d1:{d:"Allongé sur le ventre, bras tendus devant toi, jambes tendues, front posé au sol.",e:["Contracte le ventre et les fessiers avant de bouger : c'est ce qui protège le bas du dos.","Décolle simultanément les bras, la poitrine et les jambes de quelques centimètres seulement.","Le regard reste dirigé vers le sol pour ne pas casser la nuque en arrière.","Tiens la position haute une à deux secondes en cherchant à t'allonger, pas à monter haut.","Redescends lentement sans relâcher complètement, puis enchaîne."],v:["L'amplitude est volontairement faible : monter très haut cambre le bas du dos au lieu de le renforcer.","Ne lève jamais la tête vers le plafond, la nuque suit l'axe de la colonne.","Si tu ressens une gêne lombaire, décolle uniquement le haut du corps."],r:"Souffle en décollant, inspire en redescendant."},
  d2:{d:"Allongé sous une table solide, mains agrippées au bord largeur d'épaules, corps gainé en ligne droite, talons au sol.",e:["Vérifie la stabilité de la table avant de t'engager : elle doit être lourde et ne pas basculer.","Contracte fessiers et abdominaux pour aligner chevilles, bassin et épaules.","Tire la poitrine vers le bord de la table en amenant les coudes vers l'arrière.","Serre les omoplates l'une contre l'autre en fin de traction : c'est le dos qui travaille, pas les bras.","Redescends lentement bras tendus sans relâcher le gainage."],v:["Pour rendre l'exercice plus facile, fléchis les genoux et rapproche les pieds du buste.","Le bassin ne doit pas s'affaisser : le corps forme une ligne rigide du début à la fin.","Ne tire pas avec les seuls bras, initie le mouvement par les omoplates."],r:"Souffle en tirant, inspire en redescendant."},
  d3:{d:"Un genou et une main en appui sur un banc ou une chaise, l'autre pied au sol, dos horizontal et plat, haltère tenu bras tendu.",e:["Verrouille le dos à plat avant de commencer : c'est la position la plus importante de l'exercice.","Tire l'haltère vers la hanche, coude longeant les côtes, pas vers l'épaule.","Serre l'omoplate en fin de traction, une seconde de contraction.","Redescends lentement en laissant l'épaule s'étirer vers le bas.","Termine toutes les répétitions d'un côté avant de changer."],v:["Le buste ne doit pas tourner pour accompagner la traction : c'est la triche la plus fréquente.","Ne monte pas le coude vers l'extérieur, il reste près du corps.","Le dos reste plat, jamais arrondi."],r:"Souffle en tirant, inspire en redescendant."},
  d4:{d:"Assis ou à genoux, élastique fixé en hauteur au-dessus de toi, une extrémité dans chaque main, bras tendus vers le haut.",e:["Vérifie la solidité du point d'ancrage avant de tirer dessus.","Ouvre légèrement la poitrine et abaisse d'abord les omoplates.","Tire les mains vers les épaules en écartant les coudes vers le bas et l'extérieur.","Amène les mains à hauteur de clavicules, en serrant les omoplates.","Remonte lentement en résistant à la traction de l'élastique."],v:["Ne tire pas la nuque en arrière : le buste reste droit ou très légèrement incliné.","Le mouvement part des omoplates, pas des mains.","Vérifie l'état de l'élastique avant chaque séance."],r:"Souffle en tirant vers le bas, inspire en remontant."},
  d5:{d:"Assis au sol jambes tendues, élastique passé autour des pieds, une extrémité dans chaque main, buste droit.",e:["Redresse le buste et sors la poitrine avant de commencer.","Tire les coudes vers l'arrière en les gardant près des côtes.","Serre les omoplates en fin de traction, poitrine ouverte.","Le buste ne recule pas pour accompagner : seuls les bras et le dos travaillent.","Reviens lentement bras tendus en résistant."],v:["Ne te penche pas en arrière pour tirer plus fort, c'est le dos qui doit fournir l'effort.","Le dos reste droit, jamais arrondi, même en position bras tendus.","Les épaules ne montent pas vers les oreilles."],r:"Souffle en tirant, inspire au retour."},
  d6:{d:"Assis à la machine, cuisses bloquées sous les coussins, mains sur la barre en prise large, buste très légèrement incliné en arrière.",e:["Règle les coussins pour que tes cuisses soient fermement maintenues.","Abaisse d'abord les omoplates, avant même de plier les bras.","Tire la barre vers le haut de la poitrine, coudes vers le bas et l'extérieur.","Marque une contraction d'une seconde, poitrine ouverte.","Remonte lentement en contrôlant, jusqu'à sentir l'étirement du dos."],v:["Ne tire jamais la barre derrière la nuque : la position est risquée pour l'épaule.","Ne donne pas d'élan avec le buste, l'inclinaison reste stable.","Le retour contrôlé compte autant que la traction."],r:"Souffle en tirant, inspire en remontant."},
  d7:{d:"Assis à la machine, pieds calés, genoux légèrement fléchis, buste droit, poignée tenue à deux mains bras tendus.",e:["Redresse le buste et ouvre la poitrine avant de tirer.","Tire la poignée vers le nombril en amenant les coudes le long du corps.","Serre les omoplates en fin de traction.","Garde le buste immobile : il ne recule pas et ne se penche pas en avant.","Reviens lentement bras tendus en laissant les omoplates s'écarter."],v:["Le balancement du buste d'avant en arrière est la triche la plus courante : il annule le travail du dos.","Ne verrouille pas les genoux, garde-les légèrement fléchis.","Le dos ne s'arrondit pas en position bras tendus."],r:"Souffle en tirant, inspire au retour."},
  d8:{d:"Debout, pieds écartés de la largeur des hanches, un haltère dans chaque main devant les cuisses, genoux très légèrement fléchis.",e:["Verrouille le dos droit et sors la poitrine : cette position doit tenir pendant tout le mouvement.","Bascule le bassin vers l'arrière et descends les haltères le long des jambes.","Les haltères restent au contact des cuisses puis des tibias, jamais éloignés du corps.","Descends jusqu'à sentir l'étirement de l'arrière des cuisses, et arrête-toi si le dos veut s'arrondir.","Remonte en poussant le bassin vers l'avant et en contractant les fessiers."],v:["Le dos qui s'arrondit est la faute à ne jamais commettre sur ce mouvement : arrête l'amplitude avant.","Ne laisse pas les haltères s'éloigner du corps, le bras de levier deviendrait dangereux.","Ne cambre pas en position haute, arrête-toi à l'alignement."],r:"Inspire en descendant, souffle en remontant."},
  p1:{d:"À genoux au sol, mains posées largeur d'épaules légèrement en avant des épaules, chevilles croisées, corps aligné des genoux aux épaules.",e:["Aligne genoux, bassin et épaules : le corps forme une planche inclinée, sans casser au niveau des hanches.","Contracte le ventre et les fessiers pour verrouiller cette ligne.","Descends la poitrine vers le sol en fléchissant les coudes à environ 45° du corps.","Va jusqu'à ce que la poitrine soit à quelques centimètres du sol.","Repousse en tendant les bras, sans verrouiller les coudes en haut."],v:["Ne casse pas au niveau des hanches : c'est le défaut principal, il allège l'exercice et cambre le dos.","Les coudes ne partent pas à 90° sur les côtés, cela abîme les épaules à la longue.","Avance ou recule les mains pour ajuster la difficulté."],r:"Inspire en descendant, souffle en repoussant."},
  p2:{d:"En appui sur les mains et la pointe des pieds, mains largeur d'épaules légèrement en avant des épaules, corps en ligne droite des talons à la tête.",e:["Contracte fessiers et abdominaux pour verrouiller la ligne du corps avant de bouger.","Regarde légèrement en avant plutôt que vers le sol, pour garder la nuque alignée.","Descends en fléchissant les coudes à environ 45° du buste.","Descends jusqu'à ce que la poitrine soit à trois ou quatre centimètres du sol.","Repousse en poussant le sol loin de toi, sans verrouiller les coudes."],v:["Le bassin qui s'affaisse ou qui remonte en pointe casse tout l'intérêt du mouvement.","Ne descends pas seulement la tête : c'est la poitrine qui doit approcher le sol.","Si tu ne peux pas descendre complètement, reviens aux pompes sur les genoux plutôt que de tricher."],r:"Inspire en descendant, souffle en repoussant."},
  p3:{d:"Pieds posés sur une chaise ou une marche, mains au sol largeur d'épaules, corps en ligne droite inclinée.",e:["Commence avec une surélévation basse : plus les pieds sont hauts, plus la charge se déplace sur les épaules.","Verrouille le gainage : l'inclinaison rend l'affaissement du bassin plus tentant.","Descends la poitrine vers le sol, coudes à 45°.","Va jusqu'à quelques centimètres du sol.","Repousse en tendant les bras, sans laisser le bassin bouger."],v:["Vérifie la stabilité du support : un support qui glisse est dangereux dans cette position.","Si les épaules deviennent douloureuses, baisse la surélévation.","Le corps forme une ligne droite, pas un V."],r:"Inspire en descendant, souffle en repoussant."},
  p4:{d:"Allongé sur un banc ou au sol, un haltère dans chaque main à hauteur de poitrine, coudes fléchis, pieds à plat.",e:["Plaque le bas du dos et serre les omoplates l'une contre l'autre : c'est la base d'un développé sûr.","Positionne les haltères au niveau des pectoraux, poignets à l'aplomb des coudes.","Pousse les haltères vers le haut en les rapprochant légèrement, sans les faire se cogner.","Ne verrouille pas complètement les coudes en position haute.","Redescends lentement jusqu'à ce que les coudes arrivent au niveau du buste."],v:["Ne descends pas les coudes plus bas que le niveau du buste : l'épaule se retrouverait en position vulnérable.","Les omoplates restent serrées pendant tout le mouvement.","Ne cambre pas le dos pour pousser plus lourd."],r:"Inspire en descendant, souffle en poussant."},
  p5:{d:"Allongé sur un banc ou au sol, un haltère dans chaque main bras tendus au-dessus de la poitrine, coudes très légèrement fléchis.",e:["Garde une légère flexion des coudes du début à la fin : bras totalement tendus, l'articulation encaisse tout.","Écarte lentement les bras sur les côtés en décrivant un arc de cercle.","Descends jusqu'à sentir un étirement franc des pectoraux, sans forcer.","Marque une brève pause en position basse.","Ramène les bras en contractant la poitrine, comme si tu enserrais un gros ballon."],v:["Utilise une charge légère : ce mouvement met l'épaule en position d'étirement, ce n'est pas un exercice de force.","Les coudes gardent le même angle pendant tout le mouvement, sinon c'est un développé.","Ne descends pas plus bas que le niveau du buste."],r:"Inspire en écartant, souffle en ramenant."},
  p6:{d:"Debout, élastique passé dans le dos au niveau des omoplates, une extrémité dans chaque main à hauteur de poitrine, coudes fléchis.",e:["Vérifie que l'élastique passe bien dans le dos et non sous les bras.","Avance un pied pour stabiliser ta position.","Pousse les mains vers l'avant en tendant les bras, en les rapprochant légèrement.","Contracte la poitrine en fin de poussée, une seconde.","Reviens lentement en résistant à la traction de l'élastique."],v:["Ne te penche pas en avant pour pousser plus fort : le buste reste vertical.","Les coudes ne montent pas au-dessus des épaules.","Vérifie l'état de l'élastique avant chaque séance."],r:"Souffle en poussant, inspire au retour."},
  p7:{d:"Assis à la machine, dos plaqué au dossier, poignées à hauteur de poitrine, pieds à plat au sol.",e:["Règle la hauteur du siège pour que les poignées soient au niveau du milieu de la poitrine.","Plaque le dos et serre légèrement les omoplates contre le dossier.","Pousse les poignées vers l'avant en tendant les bras, sans verrouiller les coudes.","Marque une contraction d'une seconde en fin de poussée.","Reviens lentement jusqu'à ce que les mains arrivent au niveau du buste."],v:["Ne laisse pas les coudes partir loin en arrière : arrête le retour au niveau du buste.","Le dos ne se décolle pas du dossier pour pousser.","Les épaules restent basses, elles ne montent pas vers les oreilles."],r:"Souffle en poussant, inspire au retour."},
  e1:{d:"Debout ou assis, dos droit, un haltère dans chaque main à hauteur d'épaules, paumes vers l'avant, coudes fléchis.",e:["Contracte le ventre pour éviter de cambrer : c'est la protection du bas du dos sur ce mouvement.","Vérifie que les poignets sont à l'aplomb des coudes avant de pousser.","Pousse les haltères vers le haut en les rapprochant légèrement au-dessus de la tête.","Ne verrouille pas complètement les coudes en position haute.","Redescends lentement jusqu'à ce que les mains arrivent au niveau des oreilles."],v:["La cambrure du bas du dos est le défaut le plus courant : si tu cambres, la charge est trop lourde.","Ne pousse pas les haltères vers l'avant, la trajectoire est verticale.","Assis avec un dossier, tu limites naturellement la triche."],r:"Souffle en poussant, inspire en redescendant."},
  e2:{d:"Debout, un haltère dans chaque main le long du corps, coudes très légèrement fléchis, buste droit.",e:["Choisis une charge légère : ce mouvement se fait sur un petit muscle, l'amplitude compte plus que le poids.","Monte les bras sur les côtés en gardant les coudes légèrement fléchis.","Monte jusqu'à hauteur d'épaules, pas plus haut.","Garde les coudes plus hauts que les poignets pendant toute la montée.","Redescends lentement en contrôlant, sans laisser les bras tomber."],v:["Ne balance pas le buste pour lancer les haltères : si tu as besoin d'élan, la charge est trop lourde.","Ne monte pas au-dessus des épaules, le trapèze prendrait le relais.","Les épaules restent basses, loin des oreilles."],r:"Souffle en montant, inspire en redescendant."},
  e3:{d:"Debout au centre d'un élastique, un pied dessus, une extrémité dans chaque main à hauteur d'épaules.",e:["Vérifie que l'élastique est bien bloqué sous le pied avant de pousser.","Contracte le ventre pour éviter de cambrer.","Pousse les mains vers le haut en tendant les bras au-dessus de la tête.","La résistance augmente à mesure que tu montes, exactement là où le mouvement est le plus facile.","Redescends lentement en résistant."],v:["Ne cambre pas le bas du dos pour compenser la résistance croissante.","La trajectoire est verticale, pas vers l'avant.","Vérifie l'état de l'élastique avant chaque séance."],r:"Souffle en poussant, inspire en redescendant."},
  e4:{d:"Debout, pieds au centre de l'élastique, une extrémité dans chaque main le long du corps.",e:["Contrôle la tension de départ : l'élastique doit être légèrement tendu bras le long du corps.","Monte les bras sur les côtés, coudes très légèrement fléchis.","Monte jusqu'à hauteur d'épaules seulement.","Marque une brève pause en haut, où la résistance est maximale.","Redescends lentement en résistant à la traction."],v:["Ne monte pas plus haut que les épaules.","Le buste reste immobile, sans balancement.","Si l'élastique est trop dur, écarte les pieds pour réduire la tension."],r:"Souffle en montant, inspire en redescendant."},
  e5:{d:"Assis à la machine, dos plaqué au dossier, poignées à hauteur d'épaules, pieds à plat.",e:["Règle le siège pour que les poignées soient au niveau des épaules, pas plus haut.","Plaque le dos contre le dossier et contracte le ventre.","Pousse les poignées vers le haut jusqu'à presque tendre les bras.","Ne verrouille pas les coudes en position haute.","Redescends lentement jusqu'au niveau des oreilles."],v:["Ne descends pas plus bas que les oreilles, l'épaule se retrouverait en position vulnérable.","Le dos reste au dossier, sans décollement.","Les épaules ne remontent pas vers les oreilles en fin de poussée."],r:"Souffle en poussant, inspire en redescendant."},
  e6:{d:"En appui sur les mains et les pieds, bassin haut, corps plié en V inversé, mains largeur d'épaules.",e:["Recule les pieds vers les mains pour accentuer le V : plus le bassin est haut, plus la charge passe sur les épaules.","Regarde entre tes mains, nuque alignée.","Descends le sommet du crâne vers le sol en fléchissant les coudes vers l'arrière.","Va jusqu'à quelques centimètres du sol, sans y poser la tête.","Repousse en tendant les bras, en gardant le bassin haut."],v:["Le bassin ne doit pas descendre pendant le mouvement, sinon l'exercice devient une pompe classique.","Ne pose jamais le poids du corps sur la tête.","Commence avec un V peu marqué et accentue-le progressivement."],r:"Inspire en descendant, souffle en repoussant."},
  b1:{d:"Assis au bord d'une chaise stable, mains agrippées au bord de part et d'autre des hanches, doigts vers l'avant.",e:["Vérifie que la chaise ne peut pas basculer ou glisser avant de t'engager.","Avance les fesses dans le vide, en gardant le dos près du bord.","Descends en fléchissant les coudes vers l'arrière, jusqu'à environ 90°.","Les coudes restent serrés et pointés vers l'arrière, jamais écartés sur les côtés.","Repousse en tendant les bras, sans verrouiller complètement."],v:["Ne descends pas plus bas que 90° : l'épaule se retrouverait en position de contrainte forte.","Garde les épaules basses, loin des oreilles, pendant tout le mouvement.","Genoux fléchis pour alléger, tendus pour durcir."],r:"Inspire en descendant, souffle en repoussant."},
  b2:{d:"Debout, un haltère dans chaque main bras tendus le long du corps, paumes vers l'avant, coudes collés aux côtes.",e:["Verrouille les coudes contre les côtes : ils ne doivent pas bouger d'un centimètre pendant le mouvement.","Monte les haltères en fléchissant les coudes, sans bouger les épaules.","Monte jusqu'à ce que les avant-bras approchent les biceps.","Marque une contraction d'une seconde en position haute.","Redescends lentement, en contrôlant jusqu'à l'extension complète."],v:["Le balancement du buste pour lancer la charge annule tout le travail : si tu en as besoin, allège.","Les coudes qui avancent transforment le mouvement en soulevé d'épaules.","Descends complètement à chaque répétition, les demi-amplitudes limitent les résultats."],r:"Souffle en montant, inspire en redescendant."},
  b3:{d:"Debout ou assis, un haltère tenu à deux mains au-dessus de la tête, bras tendus, coudes près des oreilles.",e:["Contracte le ventre pour éviter de cambrer : le bras de levier au-dessus de la tête y pousse fortement.","Descends l'haltère derrière la tête en fléchissant uniquement les coudes.","Les coudes restent pointés vers le plafond et près des oreilles, ils ne s'écartent pas.","Descends jusqu'à sentir l'étirement des triceps, sans forcer.","Remonte en tendant les bras, sans verrouiller brutalement."],v:["Les coudes qui s'écartent sur les côtés sont le défaut principal : ils déplacent le travail hors du triceps.","Ne cambre pas le bas du dos, garde les côtes basses.","Commence léger, la position au-dessus de la tête est exigeante pour l'épaule."],r:"Inspire en descendant, souffle en tendant."},
  b4:{d:"Debout sur l'élastique, pieds écartés, une extrémité dans chaque main bras tendus le long du corps, paumes vers l'avant.",e:["Verrouille les coudes contre les côtes avant de commencer.","Monte les mains en fléchissant les coudes, contre la résistance de l'élastique.","La résistance est maximale en haut, exactement là où le biceps est le plus contracté.","Marque une pause d'une seconde en position haute.","Redescends lentement en résistant, sans laisser l'élastique te ramener."],v:["Le retour contrôlé est la moitié du travail : ne laisse jamais l'élastique se détendre d'un coup.","Les coudes ne quittent pas les côtes.","Le buste reste immobile."],r:"Souffle en montant, inspire en redescendant."},
  b5:{d:"Buste incliné vers l'avant à environ 45°, dos droit, élastique sous les pieds, coudes remontés le long des côtes.",e:["Verrouille le buste incliné et le dos plat : cette position ne bouge plus jusqu'à la fin de la série.","Amène les coudes haut, le long des côtes, avant de commencer.","Tends les avant-bras vers l'arrière en gardant les coudes parfaitement immobiles.","Marque une contraction franche en fin d'extension, bras tendus.","Reviens lentement sans laisser les coudes descendre."],v:["Le coude qui descend pendant le mouvement est le défaut principal : il annule le travail du triceps.","Le buste ne se redresse pas pour aider.","Charge légère : ce mouvement se joue sur la contraction, pas sur la résistance."],r:"Souffle en tendant, inspire au retour."},
  b6:{d:"Assis à la machine, bras posés sur le pupitre incliné, aisselles calées contre le rebord, mains sur la poignée.",e:["Règle le siège pour que tes aisselles soient bien calées contre le haut du pupitre.","Le pupitre bloque les coudes : la triche par balancement devient impossible, c'est tout l'intérêt.","Fléchis les coudes pour monter la poignée vers les épaules.","Marque une contraction d'une seconde en haut.","Redescends lentement jusqu'à l'extension presque complète."],v:["Ne relâche pas complètement en bas, l'articulation encaisserait la charge d'un coup.","Les fesses restent sur le siège, sans décollement.","Les épaules ne montent pas vers les oreilles."],r:"Souffle en montant, inspire en redescendant."},
  b7:{d:"Debout face à la machine, barre ou corde tenue à deux mains, coudes fléchis et collés aux côtes, buste très légèrement incliné.",e:["Colle les coudes aux côtes : ils constituent le seul point fixe du mouvement.","Tends les avant-bras vers le bas jusqu'à l'extension complète.","Marque une contraction franche en bas, triceps serrés.","Remonte lentement jusqu'à ce que les avant-bras soient à l'horizontale.","Ne laisse pas les coudes s'écarter ni remonter pendant le retour."],v:["Les coudes qui s'éloignent des côtes transfèrent le travail sur le dos et les épaules.","Ne te penche pas en avant pour pousser plus lourd avec le poids du corps.","Le buste reste immobile pendant toute la série."],r:"Souffle en tendant vers le bas, inspire en remontant."},
  b8:{d:"Une main en appui sur chacun de deux bancs parallèles ou sur les accoudoirs, bras tendus, corps en suspension, jambes fléchies ou tendues.",e:["Vérifie la stabilité et l'écartement des deux appuis avant de t'engager.","Descends en fléchissant les coudes vers l'arrière, buste très légèrement incliné vers l'avant.","Descends jusqu'à ce que les bras forment un angle droit, pas davantage.","Garde les épaules basses et loin des oreilles pendant toute la descente.","Repousse en tendant les bras, sans verrouiller les coudes."],v:["Ne descends pas plus bas que 90° : c'est là que l'épaule devient vulnérable.","Si les épaules remontent vers les oreilles, tu descends trop bas ou l'exercice est trop dur.","Fléchis les genoux pour alléger, tends-les pour durcir."],r:"Inspire en descendant, souffle en repoussant."},
  a1:{d:"En appui sur les avant-bras et la pointe des pieds, coudes à l'aplomb des épaules, corps en ligne droite des talons à la tête.",e:["Place les coudes exactement sous les épaules : plus en avant, tu tires sur les lombaires.","Rentre le ventre et serre les fessiers pour verrouiller le bassin.","Rentre légèrement le menton, nuque dans l'axe de la colonne.","Pousse les avant-bras dans le sol et écarte activement les omoplates.","Tiens la position immobile pendant toute la durée prévue."],v:["Le bassin qui s'affaisse annule le travail et charge le bas du dos : arrête la série dès qu'il descend.","Le bassin qui remonte en pointe est l'autre défaut : le corps doit rester rectiligne.","Mieux vaut vingt secondes parfaites qu'une minute affaissée."],r:"Respire régulièrement et sans blocage : ne tiens jamais la planche en apnée."},
  a2:{d:"Allongé sur le dos, genoux fléchis, pieds à plat au sol, mains posées aux tempes ou croisées sur la poitrine.",e:["Plaque le bas du dos au sol : il ne doit jamais se décoller pendant le mouvement.","Rentre légèrement le menton, sans le coller à la poitrine.","Décolle les épaules du sol en enroulant le haut du dos, de quelques centimètres seulement.","Marque une contraction d'une seconde en position haute.","Redescends lentement sans reposer complètement la tête."],v:["Ne tire jamais sur la nuque avec les mains : elles ne font qu'accompagner.","L'amplitude est faible : monter très haut fait travailler les fléchisseurs de hanche, pas les abdominaux.","Ne donne pas d'élan avec les bras."],r:"Souffle en montant, inspire en redescendant."},
  a3:{d:"En position de planche bras tendus, mains sous les épaules, corps en ligne droite.",e:["Verrouille le gainage avant de commencer : le bassin ne doit pas bouger de tout l'exercice.","Ramène un genou vers la poitrine sans lever le bassin.","Repousse cette jambe en arrière tout en amenant l'autre genou vers l'avant.","Alterne à cadence régulière, en gardant les épaules à l'aplomb des mains.","Continue pendant toute la durée prévue, en maintenant la ligne du corps."],v:["Le bassin qui monte et descend à chaque appui est le défaut principal : ralentis la cadence.","Les mains ne bougent pas et restent sous les épaules.","Mieux vaut un rythme modéré et stable qu'une cadence rapide et désordonnée."],r:"Respire de façon régulière et rythmée, sans bloquer."},
  a4:{d:"Allongé sur le côté, appui sur l'avant-bras, coude sous l'épaule, jambes tendues et superposées, bassin décollé.",e:["Place le coude exactement sous l'épaule avant de décoller le bassin.","Empile épaule, hanche et cheville sur une même ligne verticale.","Décolle le bassin et cherche à t'allonger, en poussant le sol avec l'avant-bras.","Garde le bras libre le long du corps ou tendu vers le plafond.","Tiens la position sans laisser le bassin redescendre."],v:["Le bassin qui s'affaisse vers le sol est le défaut le plus fréquent : arrête la série à ce moment.","Le corps ne doit pas basculer vers l'avant ou l'arrière, les hanches restent empilées.","Si c'est trop dur, pose les genoux au sol plutôt que de tenir une position dégradée."],r:"Respire régulièrement, sans blocage."},
  a5:{d:"Allongé sur le dos, jambes tendues, mains posées sous les fesses ou le long du corps.",e:["Glisse les mains sous les fesses : cela plaque le bas du dos et le protège.","Contracte le ventre pour verrouiller le bassin.","Monte les jambes tendues jusqu'à la verticale, ou moins haut selon ta souplesse.","Redescends lentement en contrôlant, et arrête-toi dès que le bas du dos veut se décoller.","Ne pose pas les talons au sol entre les répétitions."],v:["Le bas du dos qui se décolle est le signal d'arrêt : réduis l'amplitude basse plutôt que de forcer.","Ne donne pas d'élan avec les jambes, le mouvement est contrôlé dans les deux sens.","Fléchis les genoux pour alléger si la version jambes tendues est trop dure."],r:"Souffle en montant, inspire en redescendant."},
  a6:{d:"Assis au sol, genoux fléchis, pieds au sol ou légèrement décollés, buste incliné vers l'arrière à environ 45°, mains jointes devant la poitrine.",e:["Redresse le buste et garde le dos droit, jamais arrondi, malgré l'inclinaison.","Contracte le ventre pour maintenir cette position tout au long de la série.","Pivote le buste d'un côté en amenant les mains vers la hanche.","La rotation vient du buste et non des bras : les épaules et le bassin tournent ensemble.","Reviens au centre et pivote de l'autre côté."],v:["Le dos arrondi est le défaut à corriger en priorité : redresse-toi même si l'exercice devient plus dur.","Ne bouge pas seulement les bras, sinon les obliques ne travaillent pas.","Pose les pieds au sol pour alléger, décolle-les pour durcir."],r:"Souffle à chaque rotation, inspire au retour au centre."},
  a7:{d:"Debout, élastique fixé en hauteur d'un côté, les deux mains tenant l'extrémité bras tendus en diagonale au-dessus de l'épaule.",e:["Vérifie la solidité du point d'ancrage avant de tirer.","Écarte les pieds pour une base stable et fléchis légèrement les genoux.","Tire les mains en diagonale vers la hanche opposée, comme un coup de hache.","La rotation vient du buste et du bassin, les bras restent tendus.","Reviens lentement en résistant, puis change de côté à la série suivante."],v:["Ne plie pas les bras : ils forment un levier rigide, le travail vient de la rotation du tronc.","Garde les genoux souples, ne verrouille pas les jambes.","Le mouvement est contrôlé, jamais lancé en force."],r:"Souffle pendant la rotation descendante, inspire au retour."},
  a8:{d:"Assis ou à genoux à la machine, mains sur les poignées, buste droit au départ.",e:["Règle la charge pour pouvoir enrouler le buste sans être arraché de ta position.","Verrouille les hanches : elles ne doivent pas bouger, seul le buste s'enroule.","Enroule le haut du dos vers l'avant en rapprochant le sternum du bassin.","Marque une contraction d'une seconde en position enroulée.","Reviens lentement en déroulant, sans laisser la charge te redresser d'un coup."],v:["Ne tire pas avec les bras, ils ne servent qu'à tenir : le mouvement vient des abdominaux.","Si les hanches bougent, la charge est trop lourde.","L'amplitude est courte, c'est un enroulement et non une flexion complète."],r:"Souffle en enroulant, inspire en revenant."},
  c1:{d:"Debout, pieds serrés, bras le long du corps, genoux souples.",e:["Saute en écartant les pieds au-delà de la largeur des épaules.","Monte simultanément les bras sur les côtés jusqu'au-dessus de la tête.","Enchaîne immédiatement par un saut qui ramène pieds et bras à la position de départ.","Amortis chaque réception sur la plante du pied, genoux légèrement fléchis.","Garde une cadence régulière pendant toute la durée prévue."],v:["Ne retombe jamais jambes raides : l'amortissement se fait toujours genoux fléchis.","Si les articulations sont sensibles, remplace par la version sans saut.","Garde le buste droit, ne te penche pas en avant avec la fatigue."],r:"Respire de façon rythmée et continue, sans chercher à synchroniser chaque saut."},
  c2:{d:"Debout, pieds écartés de la largeur des hanches, bras fléchis devant toi.",e:["Monte un genou vers la poitrine, aussi haut que possible.","Repose le pied et enchaîne immédiatement avec l'autre genou.","Reste sur la plante des pieds, sans poser les talons.","Balance les bras naturellement en opposition, comme en course.","Maintiens la cadence pendant toute la durée prévue."],v:["Ne te penche pas en arrière pour monter les genoux plus haut : le buste reste vertical.","Garde le ventre contracté pour protéger le bas du dos.","Ralentis la cadence plutôt que de dégrader la posture."],r:"Respire de façon rythmée et continue."},
  c3:{d:"Debout, pieds écartés de la largeur des épaules, dans un espace dégagé.",e:["Descends en squat et pose les mains au sol devant tes pieds.","Projette les deux pieds en arrière pour arriver en position de planche, corps gainé.","Effectue une pompe si ton niveau le permet, sinon passe directement à l'étape suivante.","Ramène les pieds d'un saut vers les mains, en position accroupie.","Détends-toi vers le haut en sautant bras tendus, puis enchaîne."],v:["Ne laisse pas le bassin s'affaisser au moment où tu arrives en planche : c'est là que le dos est le plus exposé.","Enlève le saut et la pompe pour commencer, l'enchaînement seul suffit à essouffler.","Arrête la série dès que la technique se dégrade, c'est un mouvement à risque en fatigue."],r:"Souffle à chaque saut vertical, inspire pendant la phase au sol."},
  c4:{d:"Debout, corde tenue une extrémité dans chaque main, coudes près du corps, corde derrière les talons.",e:["Règle la longueur : les poignées doivent arriver aux aisselles quand tu marches sur le milieu de la corde.","Fais tourner la corde par les poignets, pas par les épaules.","Saute juste assez haut pour laisser passer la corde, deux ou trois centimètres suffisent.","Reste sur la plante des pieds, talons proches du sol sans le toucher.","Garde une cadence régulière plutôt que rapide."],v:["Les grands mouvements de bras sont le défaut principal : ils fatiguent les épaules et déstabilisent le rythme.","Ne saute pas haut, l'énergie dépensée est inutile.","Commence par de courtes séries, la coordination vient avant l'endurance."],r:"Respire de façon rythmée et continue."},
  c5:{d:"Assis sur la machine, dos droit, pieds calés sur les pédales ou sur les cales du rameur.",e:["Règle la position du siège avant de commencer : sur un vélo, la jambe doit être presque tendue en bas de course.","Démarre par trois minutes à faible intensité pour échauffer les articulations.","Installe ensuite une allure régulière que tu peux tenir sans t'essouffler complètement.","Sur rameur, pousse d'abord avec les jambes, puis tire avec les bras : jamais l'inverse.","Termine par deux minutes à faible intensité pour faire redescendre le rythme cardiaque."],v:["Sur rameur, ne tire pas d'abord avec les bras : ce sont les jambes qui fournissent l'essentiel de la puissance.","Sur vélo, ne balance pas le bassin d'un côté à l'autre, signe que la selle est trop haute.","Le dos reste droit, jamais arrondi, même en fin de séance."],r:"Respire profondément et régulièrement, sans bloquer sur les phases d'effort."},
  c6:{d:"En position de planche bras tendus, mains sous les épaules, corps en ligne droite.",e:["Verrouille le gainage : le bassin doit rester parfaitement immobile malgré la vitesse.","Ramène un genou vers la poitrine puis change de jambe le plus vite possible.","Les mains restent fixes, à l'aplomb des épaules.","Cherche la fréquence des jambes, pas l'amplitude du genou.","Tiens la cadence pendant toute la durée prévue."],v:["Le bassin qui rebondit de haut en bas à chaque appui annule tout le travail : c'est le signe qu'il faut ralentir.","Version plus exigeante que les mountain climbers classiques : maîtrise d'abord la version lente.","Arrête dès que les épaules commencent à s'affaisser."],r:"Respire rapidement et régulièrement, sans jamais bloquer."},
  d9:{d:"Allongé sur le ventre, bras tendus devant, jambes tendues, front au sol.",e:["Contracte le ventre et les fessiers pour protéger le bas du dos.","Décolle simultanément le bras droit et la jambe gauche de quelques centimètres.","Cherche à t'allonger dans les deux directions plutôt qu'à monter haut.","Tiens une seconde, redescends sans poser complètement, puis change de côté.","Le regard reste vers le sol pendant tout l'exercice."],v:["Le travail en diagonale sollicite la chaîne croisée : ne monte jamais les deux bras ensemble ici.","Ne lève pas la tête vers le plafond.","L'amplitude reste faible, l'objectif est la contraction et non la hauteur."],r:"Souffle en décollant, inspire en redescendant."},
  d10:{d:"Allongé sur le ventre, mains à plat sous les épaules, coudes fléchis, jambes tendues.",e:["Plaque le bassin au sol : il ne se décolle jamais dans cet exercice.","Décolle la poitrine en contractant le bas du dos, en poussant à peine sur les mains.","Les bras accompagnent le mouvement, ils ne le produisent pas.","Monte jusqu'à sentir la contraction lombaire, sans forcer l'extension.","Redescends lentement et sans à-coup."],v:["Si tu pousses fort sur les bras, c'est une posture d'étirement et non un exercice de renforcement.","Le bassin qui se décolle transforme le mouvement en cambrure excessive.","Arrête l'amplitude dès qu'une gêne apparaît dans le bas du dos."],r:"Souffle en montant, inspire en redescendant."},
  d11:{d:"Allongé sur le ventre, bras tendus devant, jambes tendues, tout le corps légèrement décollé du sol.",e:["Décolle d'abord bras et jambes de quelques centimètres et maintiens cette hauteur.","Contracte le ventre et les fessiers pour garder le bassin stable.","Effectue de petits battements alternés des bras et des jambes, comme une nage.","Les membres ne touchent jamais le sol pendant la série.","Garde une cadence lente et régulière."],v:["Ne laisse pas la poitrine retomber au sol entre les battements : la tension reste continue.","Le regard reste vers le sol, nuque alignée.","Battements de faible amplitude : c'est le maintien qui fatigue, pas la vitesse."],r:"Respire régulièrement pendant toute la durée, sans bloquer."},
  d12:{d:"Allongé sur le ventre, front posé au sol, bras le long du corps, jambes tendues.",e:["Décolle les bras et tends-les au-dessus de la tête en formant un Y, pouces vers le plafond.","Tiens deux secondes en serrant les omoplates, puis redescends sans poser.","Écarte ensuite les bras sur les côtés en formant un T, et tiens deux secondes.","Plie enfin les coudes près du corps en formant un W, omoplates serrées au maximum.","Cette séquence de trois positions compte pour une répétition."],v:["Le geste vient des omoplates, jamais des mains : cherche à les rapprocher l'une de l'autre.","Ne décolle pas la poitrine du sol, seuls les bras travaillent.","Amplitude faible et contraction franche valent mieux que de grands mouvements relâchés."],r:"Souffle sur chaque position tenue, inspire pendant la transition."},
  d13:{d:"À quatre pattes, mains sous les épaules, genoux sous les hanches, dos plat.",e:["Contracte le ventre pour verrouiller le bassin : c'est lui qui doit rester immobile.","Tends simultanément le bras droit devant et la jambe gauche derrière.","Cherche l'alignement main-épaule-bassin-talon sur une ligne horizontale.","Tiens deux secondes sans laisser le bassin tourner ni le dos s'affaisser.","Reviens en position de départ puis alterne le côté."],v:["Le bassin qui bascule sur le côté est le défaut principal : c'est la stabilité, pas l'amplitude, qui compte.","Ne monte pas le bras ni la jambe plus haut que l'horizontale.","Si tu vacilles, réduis l'extension et concentre-toi sur le gainage."],r:"Souffle en tendant les membres, inspire en revenant."},
  d14:{d:"Debout, une serviette tenue à deux mains, bras tendus devant toi à hauteur de poitrine, mains écartées de la largeur des épaules.",e:["Vérifie que la serviette est bien tendue entre tes mains avant de commencer.","Tire fort sur les deux extrémités, comme si tu voulais la déchirer.","Écarte simultanément les coudes vers l'arrière en serrant les omoplates.","Maintiens cette tension maximale sans bouger pendant toute la durée prévue.","Relâche progressivement à la fin, sans lâcher d'un coup."],v:["L'intensité dépend entièrement de la force que tu appliques : sans tension réelle, l'exercice ne sert à rien.","Les épaules restent basses, loin des oreilles.","Ne bloque pas la respiration malgré l'effort de traction."],r:"Respire régulièrement, sans apnée : c'est un maintien sous tension, pas un effort explosif."},
  d15:{d:"Allongé sous une table solide, mains agrippées au bord, genoux fléchis et pieds à plat au sol, corps gainé.",e:["Vérifie la stabilité de la table : elle doit être lourde et ne pas pouvoir basculer.","Fléchis les genoux et rapproche les pieds du buste : cette position allège nettement l'exercice.","Contracte fessiers et abdominaux pour aligner genoux, bassin et épaules.","Tire la poitrine vers le bord en amenant les coudes vers l'arrière et en serrant les omoplates.","Redescends lentement bras tendus sans relâcher le gainage."],v:["Plus tu tends les jambes, plus l'exercice devient dur : ajuste progressivement.","Le bassin ne s'affaisse pas, le corps garde sa ligne.","Initie la traction par les omoplates et non par les bras."],r:"Souffle en tirant, inspire en redescendant."},
  d16:{d:"Assis au sol, jambes tendues devant, mains posées derrière toi, doigts dirigés vers les pieds.",e:["Place les mains à environ vingt centimètres derrière les hanches, doigts vers l'avant.","Pousse dans les mains et les talons pour décoller le bassin.","Monte jusqu'à former une ligne droite des épaules aux chevilles.","Ouvre la poitrine en serrant les omoplates, sans laisser la tête tomber en arrière.","Tiens la position immobile pendant toute la durée prévue."],v:["Le bassin qui s'affaisse annule le travail : arrête la série dès qu'il descend.","Position exigeante pour les épaules en extension : arrête immédiatement en cas de gêne.","Fléchis les genoux et pose les pieds à plat pour une version allégée."],r:"Respire régulièrement, sans bloquer."},
  d17:{d:"Allongé sur le ventre, bras tendus devant, paumes vers le sol, front posé au sol.",e:["Décolle les bras de quelques centimètres, tendus devant toi.","Ramène les coudes vers les hanches en pliant les bras, comme si tu tirais une barre invisible.","Serre les omoplates au maximum en fin de traction.","Marque une pause d'une seconde dans cette position contractée.","Retends les bras vers l'avant sans les reposer au sol."],v:["Les bras ne touchent pas le sol entre les répétitions, la tension reste continue.","Ne décolle pas la poitrine, seuls les bras et les omoplates travaillent.","Cherche la contraction entre les omoplates, pas la vitesse d'exécution."],r:"Souffle en tirant les coudes en arrière, inspire en retendant."},
  d18:{d:"Debout ou à quatre pattes, bras tendus devant toi, épaules relâchées.",e:["Garde les coudes parfaitement tendus : ils ne se plient à aucun moment.","Rapproche les omoplates l'une de l'autre, comme pour tenir un crayon entre elles.","Le mouvement est très court, quelques centimètres seulement.","Tiens deux secondes en contraction maximale.","Relâche lentement sans laisser les épaules s'affaisser vers l'avant."],v:["Si tu plies les coudes, ce n'est plus une rétraction mais un tirage.","Les épaules ne montent pas vers les oreilles : elles reculent, elles ne remontent pas.","Mouvement essentiel pour préparer le dos aux exercices plus lourds, ne le néglige pas malgré son apparente simplicité."],r:"Souffle en serrant les omoplates, inspire en relâchant."},
  p8:{d:"En position de pompe, mains sous la poitrine, pouces et index se touchant pour former un losange.",e:["Place le losange exactement sous le sternum, pas sous le visage.","Contracte le gainage pour aligner talons, bassin et épaules.","Descends en gardant les coudes frôlant les côtes, jamais écartés.","Descends jusqu'à ce que la poitrine touche presque tes mains.","Repousse en tendant les bras, sans verrouiller les coudes."],v:["Les coudes qui s'écartent transforment l'exercice en pompe classique et sollicitent l'épaule inutilement.","Si tes poignets sont sensibles, la position est exigeante : commence sur les genoux.","Le bassin ne s'affaisse pas."],r:"Inspire en descendant, souffle en repoussant."},
  p9:{d:"En position de pompe, mains nettement plus écartées que la largeur des épaules.",e:["Écarte les mains d'environ une fois et demie la largeur des épaules, pas davantage.","Verrouille le gainage avant de descendre.","Descends la poitrine vers le sol en ouvrant les coudes à environ 45°.","Va jusqu'à ce que la poitrine soit à quelques centimètres du sol.","Repousse en pensant à rapprocher les mains vers l'intérieur, sans les bouger."],v:["N'écarte pas les mains à l'extrême : au-delà, l'amplitude chute et l'épaule se retrouve en contrainte.","Les coudes ne partent pas à 90° sur les côtés.","Amplitude réduite est normale sur cette variante : ne force pas pour descendre plus bas."],r:"Inspire en descendant, souffle en repoussant."},
  p10:{d:"Mains posées sur une surface stable et surélevée — table, plan de travail ou dossier de canapé — pieds reculés, corps en ligne inclinée.",e:["Vérifie la stabilité du support avant de t'appuyer dessus.","Plus le support est haut, plus l'exercice est facile : c'est le réglage principal.","Verrouille le gainage pour aligner talons, bassin et épaules.","Descends la poitrine vers le support, coudes à environ 45°.","Repousse en tendant les bras, sans casser au niveau des hanches."],v:["Idéal pour progresser vers la pompe complète : baisse le support progressivement au fil des semaines.","Le corps forme une ligne droite, pas un V.","Un support glissant est dangereux : vérifie l'adhérence."],r:"Inspire en descendant, souffle en repoussant."},
  p11:{d:"En position de pompe, mains très écartées, bien au-delà de la largeur des épaules.",e:["Écarte largement les mains, davantage que pour une pompe prise large.","Descends en pliant un seul bras, l'autre restant tendu sur le côté.","Tout le poids du corps bascule sur le bras fléchi.","Descends aussi bas que ton contrôle le permet, puis repousse sur ce même bras.","Alterne le côté à chaque répétition."],v:["Étape intermédiaire vers la pompe à un bras : maîtrise d'abord une vingtaine de pompes classiques.","Le bras tendu ne pousse pas, il ne sert qu'au maintien.","Le bassin reste face au sol, sans rotation."],r:"Inspire en descendant, souffle en repoussant."},
  p12:{d:"En position de pompe, mains placées au niveau de la taille plutôt que des épaules, doigts orientés légèrement vers l'arrière.",e:["Recule les mains jusqu'au niveau de la taille : c'est ce décalage qui crée la difficulté.","Penche le buste vers l'avant, épaules en avant des mains.","Verrouille le gainage, le bassin ne doit pas s'affaisser.","Descends en gardant les coudes près du corps et le buste incliné vers l'avant.","Repousse en maintenant cette inclinaison, sans laisser les hanches remonter."],v:["Variante exigeante pour les poignets et les épaules : échauffe-les soigneusement avant.","Le déséquilibre vers l'avant est volontaire, mais le corps reste une ligne droite.","Arrête immédiatement en cas de douleur au poignet."],r:"Inspire en descendant, souffle en repoussant."},
  p13:{d:"En position de pompe classique, mains largeur d'épaules, corps gainé.",e:["Descends comme une pompe classique, en contrôlant.","Repousse le plus explosivement possible pour décoller les mains du sol.","Commence sans chercher à claquer des mains : décoller de quelques centimètres suffit.","Amortis la réception en pliant immédiatement les coudes pour absorber l'impact.","Enchaîne la descente suivante dans le même mouvement."],v:["Ne réceptionne jamais bras tendus : les coudes doivent plier dès le contact.","Exige une base solide : maîtrise vingt pompes classiques avant d'aborder cette variante.","Arrête la série dès que la réception devient dure ou bruyante."],r:"Souffle explosivement à la poussée, inspire pendant la descente."},
  p14:{d:"En position de pompe classique, mains largeur d'épaules, corps gainé.",e:["Descends en comptant quatre secondes pleines, très lentement.","Marque une pause d'une seconde poitrine à quelques centimètres du sol.","Repousse à vitesse normale, en une seconde environ.","Ne marque aucune pause en position haute, enchaîne directement.","Compte à voix haute ou mentalement : la précision du tempo fait tout l'exercice."],v:["Le tempo est l'exercice : accélérer la descente annule tout l'intérêt de la variante.","Le nombre de répétitions sera nettement plus faible que sur des pompes normales, c'est attendu.","Garde le gainage jusqu'au bout malgré la durée de la tension."],r:"Inspire pendant les quatre secondes de descente, souffle à la remontée."},
  p15:{d:"En position de pompe sur un sol lisse, un chiffon ou une serviette sous chaque main, bras tendus.",e:["Teste d'abord le glissement des chiffons sur ton sol avant de charger le mouvement.","Verrouille le gainage : cet exercice exige un tronc très solide.","Écarte lentement les bras sur les côtés, coudes très légèrement fléchis.","Va jusqu'à sentir l'étirement des pectoraux, sans jamais forcer.","Ramène les mains en contractant la poitrine, comme pour refermer les bras."],v:["N'écarte pas trop loin au début : la position d'étirement sous charge est la plus risquée pour l'épaule.","Garde les coudes légèrement fléchis en permanence.","Commence à genoux pour apprendre le geste."],r:"Inspire en écartant, souffle en ramenant."},
  p16:{d:"À quatre pattes puis en V inversé, fesses hautes, mains et pieds au sol, bras tendus.",e:["Démarre en V inversé, bassin haut et bras tendus.","Descends la poitrine en la faisant passer au ras du sol, en un mouvement fluide vers l'avant.","Redresse ensuite le buste bras tendus, hanches basses, poitrine ouverte.","Reviens en poussant le bassin vers le haut et l'arrière pour retrouver le V.","Enchaîne les répétitions en gardant le mouvement continu et fluide."],v:["Mouvement complexe : décompose-le lentement plusieurs fois avant de l'enchaîner.","Ne force pas l'extension du dos en position basse, va jusqu'où c'est confortable.","Épaules et poignets sont fortement sollicités : échauffe-les avant."],r:"Inspire en descendant vers l'avant, souffle en revenant en V."},
  e7:{d:"Pieds posés sur une chaise, mains au sol largeur d'épaules, corps plié en V inversé avec le bassin haut.",e:["Vérifie la stabilité de la chaise avant d'y poser les pieds.","Recule les mains pour que le buste soit aussi vertical que possible.","Regarde entre tes mains, nuque alignée avec la colonne.","Descends le sommet du crâne vers le sol en fléchissant les coudes vers l'arrière.","Repousse en tendant les bras, sans laisser le bassin descendre."],v:["Variante exigeante : maîtrise le pike push-up au sol avant de surélever les pieds.","Ne pose jamais le poids du corps sur la tête.","Arrête immédiatement en cas de vertige ou de gêne cervicale."],r:"Inspire en descendant, souffle en repoussant."},
  e8:{d:"Debout, pieds écartés de la largeur des hanches, buste droit.",e:["Monte les bras tendus sur les côtés jusqu'à hauteur exacte des épaules.","Tourne les paumes vers le sol et garde les coudes tendus.","Abaisse activement les épaules, loin des oreilles.","Tiens la position parfaitement immobile pendant toute la durée prévue.","Relâche progressivement en fin de série, sans laisser tomber les bras."],v:["Les bras qui descendent sous la ligne des épaules annulent l'exercice : mieux vaut arrêter la série.","Les épaules ne remontent pas vers les oreilles malgré la brûlure.","La brûlure arrive très vite malgré l'absence de charge, c'est normal."],r:"Respire régulièrement et sans blocage pendant tout le maintien."},
  e9:{d:"Debout, bras tendus sur les côtés à hauteur d'épaules, paumes vers le sol.",e:["Monte les bras à hauteur exacte des épaules et garde cette hauteur.","Dessine de petits cercles vers l'avant, d'une vingtaine de centimètres de diamètre.","Effectue la moitié de la durée dans ce sens.","Inverse ensuite le sens de rotation pour la seconde moitié.","Garde les bras à la même hauteur du début à la fin."],v:["Les bras qui redescendent progressivement sont le défaut principal : surveille la hauteur.","Petits cercles contrôlés valent mieux que de grands mouvements relâchés.","Les épaules restent basses."],r:"Respire régulièrement pendant toute la durée."},
  e10:{d:"En position de planche bras tendus, mains sous les épaules, corps en ligne droite.",e:["Verrouille le gainage en position de planche.","Pousse les hanches vers le haut et l'arrière pour former un V inversé.","En position haute, pousse activement le sol avec les mains et tends complètement les bras.","Cherche à allonger la colonne plutôt qu'à descendre les talons au sol.","Reviens en planche en contrôlant, sans laisser le bassin s'affaisser."],v:["Ne laisse pas le bassin tomber au retour en planche : c'est là que le dos est exposé.","Les talons n'ont pas besoin de toucher le sol, cela dépend de ta souplesse.","Le mouvement est lent et contrôlé, jamais lancé."],r:"Souffle en poussant les hanches vers le haut, inspire en revenant en planche."},
  e11:{d:"Face à un mur, mains posées au sol à environ vingt centimètres de la plinthe.",e:["Place les mains largeur d'épaules, à vingt centimètres du mur.","Remonte les pieds le long du mur, une jambe après l'autre, en marchant.","Monte progressivement jusqu'à te retrouver tête en bas, corps proche de la verticale.","Garde les bras tendus, le corps gainé et le regard entre les mains.","Tiens quelques secondes puis redescends une jambe après l'autre, prudemment."],v:["Ne descends jamais brutalement : la sortie de position est le moment le plus risqué.","Arrête immédiatement en cas de vertige, de bourdonnement ou de tension cervicale.","Commence par des maintiens très courts, quelques secondes suffisent au début."],r:"Respire régulièrement, sans apnée : le sang afflue déjà vers la tête."},
  e12:{d:"Allongé sur le ventre, bras tendus devant en formant un Y, pouces dirigés vers le plafond, front au sol.",e:["Écarte les bras en Y, à environ 45° de l'axe du corps.","Tourne les pouces vers le plafond : cette rotation cible l'arrière de l'épaule.","Décolle les bras le plus haut possible en serrant les omoplates.","Garde la poitrine au sol, seuls les bras se lèvent.","Tiens une seconde en haut puis redescends sans poser."],v:["Ne décolle pas la poitrine, cela transformerait l'exercice en extension lombaire.","La rotation des pouces vers le plafond est essentielle : paumes au sol, l'exercice perd sa cible.","Amplitude faible et contraction franche."],r:"Souffle en décollant les bras, inspire en redescendant."},
  e13:{d:"Debout, pieds écartés de la largeur des hanches, bras le long du corps.",e:["Monte les bras tendus devant toi jusqu'à hauteur exacte des épaules.","Tourne les paumes vers le sol, coudes tendus mais non verrouillés.","Abaisse les épaules, loin des oreilles.","Tiens la position immobile pendant toute la durée prévue.","Pour durcir, tiens un objet lourd du quotidien dans chaque main."],v:["Les bras qui descendent progressivement annulent le maintien : arrête plutôt la série.","Ne cambre pas le bas du dos pour compenser la charge devant toi.","Les épaules restent basses malgré la fatigue."],r:"Respire régulièrement et sans blocage."},
  e14:{d:"En position de planche, pieds contre un mur, mains au sol assez loin du mur.",e:["Commence en planche avec la plante des pieds contre la plinthe.","Recule une main de quelques centimètres vers le mur, puis l'autre.","Remonte simultanément les pieds le long de la paroi.","Progresse ainsi jusqu'à te rapprocher de la verticale, autant que ton niveau le permet.","Redescends de la même façon, en contrôlant chaque appui."],v:["Progresse de quelques centimètres à la fois : ne cherche pas la verticale dès la première séance.","Ne bloque jamais la respiration dans cette position inversée.","Arrête et redescends dès que les épaules tremblent."],r:"Respire régulièrement et sans apnée pendant toute la progression."},
  e15:{d:"Debout, coudes collés aux côtes et fléchis à 90°, une serviette tenue tendue entre les deux mains.",e:["Colle les coudes contre les côtes : ils ne quittent pas ce contact.","Vérifie que la serviette est tendue avant de commencer.","Écarte les avant-bras vers l'extérieur en tirant sur la serviette.","Va jusqu'à l'amplitude maximale confortable, sans forcer.","Reviens lentement en gardant la tension."],v:["Les coudes qui se décollent des côtes transfèrent le travail sur les épaules et le dos.","Mouvement de santé articulaire : privilégie l'amplitude et le contrôle, jamais la force.","Les épaules restent basses."],r:"Souffle en écartant, inspire au retour."},
  e16:{d:"En position de pompe classique, mains largeur d'épaules, corps gainé.",e:["Effectue une pompe complète en contrôlant la descente et la remontée.","En position haute, fais glisser une main loin devant toi en diagonale, bras tendu.","Le bassin reste parfaitement stable pendant cette extension.","Ramène la main à sa position initiale.","Alterne le côté à chaque répétition."],v:["L'extension du bras met l'épaule en position allongée sous charge : va progressivement.","Le bassin ne doit ni tourner ni s'affaisser au moment où la main s'éloigne.","Réduis la distance d'extension si tu perds la stabilité."],r:"Souffle à la poussée de la pompe, inspire pendant l'extension du bras."},
  b9:{d:"En position de pompe, mains à la largeur des épaules ou légèrement plus rapprochées.",e:["Place les mains largeur d'épaules, pas plus écartées.","Verrouille le gainage pour aligner talons, bassin et épaules.","Descends en gardant les coudes serrés contre les côtes, frôlant le buste.","Descends jusqu'à ce que la poitrine soit à quelques centimètres du sol.","Repousse en tendant les bras : la remontée est presque entièrement assurée par les triceps."],v:["Les coudes qui s'ouvrent sur les côtés déplacent le travail vers les pectoraux et l'épaule.","Le bassin ne s'affaisse pas.","Passe sur les genoux si tu ne peux pas garder les coudes serrés."],r:"Inspire en descendant, souffle en repoussant."},
  b10:{d:"À genoux ou en planche, mains posées au sol largeur d'épaules, coudes pointés vers l'avant.",e:["Place les mains devant les épaules, coudes dirigés vers l'avant et non sur les côtés.","Contracte le gainage pour verrouiller le bassin.","Descends en pliant uniquement les coudes, les avant-bras allant vers le sol.","Les coudes restent parfaitement fixes, ils ne partent ni en avant ni sur les côtés.","Remonte en tendant les bras, sans bouger les épaules."],v:["Les coudes qui glissent vers l'avant transforment le mouvement en pompe : c'est le défaut principal.","Commence à genoux, la version en planche est nettement plus exigeante.","Ne descends pas plus bas que le contrôle des coudes ne le permet."],r:"Inspire en descendant, souffle en tendant."},
  b11:{d:"Assis au sol, mains posées derrière toi doigts vers l'avant, jambes tendues devant, talons au sol.",e:["Place les mains à environ vingt centimètres derrière les hanches.","Décolle les fesses du sol en tendant les bras.","Descends en fléchissant les coudes vers l'arrière, jusqu'à environ 90°.","Les coudes restent serrés et pointés vers l'arrière.","Repousse en tendant les bras, sans verrouiller complètement."],v:["Ne descends pas plus bas que 90° : l'épaule serait mise en contrainte forte.","Les jambes tendues rendent l'exercice nettement plus lourd que genoux fléchis : commence plié.","Garde les épaules basses, loin des oreilles."],r:"Inspire en descendant, souffle en repoussant."},
  b12:{d:"Debout, une serviette passée sous un pied, les deux extrémités tenues dans les mains, coudes collés aux côtes.",e:["Passe la serviette sous la plante d'un pied et tiens fermement les extrémités.","Colle les coudes contre les côtes et fléchis-les à l'angle voulu.","Tire vers le haut comme pour un curl, tout en résistant avec la jambe.","Aucun mouvement ne doit se produire : la tension est maximale et statique.","Maintiens plusieurs secondes, puis change l'angle du coude pour la série suivante."],v:["L'intensité dépend uniquement de la force que tu appliques : sans engagement réel, l'exercice est vide.","Ne tire pas au point de perdre l'équilibre sur la jambe d'appui.","Travaille à plusieurs angles de flexion pour couvrir toute l'amplitude."],r:"Respire régulièrement, sans apnée malgré l'effort de traction."},
  b13:{d:"Départ en position de chien tête en bas, bassin haut, bras tendus, mains largeur d'épaules.",e:["Installe-toi en V inversé, bassin haut et talons vers le sol.","Descends en pliant les coudes, les avant-bras allant vers le sol.","Les hanches ne bougent pas : seuls les coudes se plient.","Descends jusqu'à ce que les avant-bras approchent le sol.","Repousse en tendant les bras, hanches toujours hautes."],v:["Les hanches qui descendent transforment l'exercice en pompe piquée : garde le bassin haut.","Variante exigeante pour les triceps et les épaules : maîtrise l'extension au sol d'abord.","Arrête en cas de gêne au poignet ou au coude."],r:"Inspire en descendant, souffle en repoussant."},
  b14:{d:"Debout face à un mur, à environ un pas de distance, mains posées à hauteur de tête largeur d'épaules.",e:["Place les mains à hauteur de tête, coudes dirigés vers le haut et serrés.","Plie uniquement les coudes pour approcher le sommet du crâne du mur.","Les coudes restent fixes et serrés, ils ne s'écartent pas sur les côtés.","Va jusqu'à ce que le front approche le mur.","Repousse en tendant les bras, sans bouger les épaules."],v:["Les coudes qui s'écartent annulent le travail du triceps : c'est le point à surveiller.","Recule les pieds pour durcir l'exercice, rapproche-les pour l'alléger.","Version idéale pour débuter le travail des triceps sans charge."],r:"Inspire en descendant, souffle en repoussant."},
  b15:{d:"Allongé sous une table solide, mains agrippées au bord en supination — paumes tournées vers toi — mains rapprochées.",e:["Vérifie la stabilité de la table avant de t'engager.","Prends une prise paumes vers toi, mains à la largeur des épaules ou plus serrées.","Contracte fessiers et abdominaux pour aligner le corps.","Tire la poitrine vers la table en pliant les coudes, qui restent près du corps.","Redescends lentement bras tendus sans relâcher le gainage."],v:["La prise en supination transfère l'effort du dos vers les biceps : c'est tout l'intérêt de cette variante.","Fléchis les genoux pour alléger, tends les jambes pour durcir.","Le bassin ne s'affaisse pas."],r:"Souffle en tirant, inspire en redescendant."},
  b16:{d:"En position de pompe, mains tournées de façon que les doigts pointent vers tes pieds.",e:["Échauffe soigneusement les poignets avant d'aborder cette variante : la position est inhabituelle.","Tourne les mains jusqu'à ce que les doigts soient dirigés vers les pieds.","Rapproche les mains légèrement du buste pour réduire la tension au poignet.","Descends lentement en gardant les coudes près du corps.","Repousse en contrôlant, sans à-coup."],v:["Arrête immédiatement en cas de douleur au poignet : cette variante ne convient pas à tout le monde.","Commence à genoux avec une amplitude très réduite.","Cette prise met les biceps en tension, chose rare au poids du corps, mais elle exige de la mobilité."],r:"Inspire en descendant, souffle en repoussant."},
  b17:{d:"Deux chaises stables placées face à face, une main en appui sur chacune, bras tendus, corps en suspension.",e:["Vérifie très soigneusement la stabilité et le poids des deux chaises avant de t'engager.","Règle l'écartement à la largeur de tes épaules, pas plus.","Descends en fléchissant les coudes vers l'arrière, buste légèrement incliné vers l'avant.","Descends jusqu'à ce que les bras forment un angle droit, pas davantage.","Repousse en tendant les bras, épaules basses."],v:["Deux chaises constituent un appui instable : ne tente pas cet exercice sur des sièges légers ou à roulettes.","Ne descends pas plus bas que 90°.","Fléchis les genoux et pose les pieds au sol pour une version allégée et plus sûre."],r:"Inspire en descendant, souffle en repoussant."},
  b18:{d:"Debout ou assis, une main placée sous le poignet opposé, bras du dessous fléchi à environ 90°.",e:["Place la main libre sous le poignet du bras à travailler.","Essaie de fléchir le bras du dessous tout en résistant avec la main du dessus.","Dose la résistance pour que le mouvement soit très lent, sans jamais s'arrêter complètement.","Effectue la montée complète sous résistance, sur environ cinq secondes.","Inverse ensuite : résiste avec le bras du dessous pendant que la main du dessus le repousse vers le bas."],v:["L'intensité dépend entièrement de ton engagement : sans résistance réelle, l'exercice ne produit rien.","Ne bloque jamais complètement le mouvement, il doit rester lent mais continu.","Change de bras à chaque série, les deux ne peuvent pas travailler en même temps."],r:"Souffle pendant la phase de montée, inspire pendant la descente."},
  a9:{d:"Allongé sur le côté, appui sur l'avant-bras, coude sous l'épaule, jambes tendues et superposées, bassin décollé.",e:["Installe une planche latérale correcte : épaule, hanche et cheville alignées.","Descends lentement la hanche vers le sol, sans jamais la poser.","Va jusqu'à quelques centimètres du sol seulement.","Remonte en contractant les obliques jusqu'à retrouver l'alignement complet.","Enchaîne à cadence lente, sans utiliser d'élan."],v:["Les épaules et les hanches restent empilées : le corps ne doit pas basculer vers l'avant ou l'arrière.","Maîtrise la planche latérale statique avant d'y ajouter le mouvement.","Cadence lente : la vitesse fait perdre le contrôle des obliques."],r:"Souffle en remontant la hanche, inspire en descendant."},
  a10:{d:"Allongé sur le dos, bras tendus au-dessus de la tête, jambes tendues.",e:["Plaque d'abord le bas du dos au sol en basculant légèrement le bassin.","Décolle simultanément les épaules et les jambes de quelques centimètres.","Le corps forme une banane, avec seulement le bas du dos en contact avec le sol.","Vérifie ce contact en permanence : si le bas du dos se décolle, remonte les jambes plus haut.","Tiens la position immobile pendant toute la durée prévue."],v:["Le bas du dos qui se creuse est le signal d'arrêt : remonte les jambes ou fléchis les genoux.","Pour alléger, ramène les bras le long du corps au lieu de les tendre derrière la tête.","Mieux vaut quinze secondes avec le dos plaqué qu'une minute avec le dos creusé."],r:"Respire régulièrement et sans blocage : ne tiens jamais cette position en apnée."},
  a11:{d:"Allongé sur le dos, bras tendus derrière la tête, jambes tendues au sol.",e:["Plaque le bas du dos et contracte le ventre avant de bouger.","Monte simultanément le buste et les jambes tendues pour former un V.","Cherche à toucher les pieds avec les mains, ou approche-les autant que possible.","Redescends lentement et de façon contrôlée, sans poser complètement.","Fléchis les genoux pour une version allégée si le mouvement complet est trop dur."],v:["Ne donne pas d'élan avec les bras : le mouvement doit venir des abdominaux.","Le bas du dos ne doit pas claquer au sol pendant la descente : contrôle jusqu'au bout.","Si tu ne peux pas monter sans élan, passe à la version genoux fléchis."],r:"Souffle en montant, inspire en redescendant."},
  a12:{d:"Allongé sur le dos, mains sous les fesses, jambes tendues et légèrement décollées du sol.",e:["Glisse les mains sous les fesses pour plaquer et protéger le bas du dos.","Décolle les talons de quelques centimètres seulement.","Effectue de petits battements alternés de haut en bas, d'une vingtaine de centimètres d'amplitude.","Les talons ne touchent jamais le sol pendant la série.","Garde une cadence régulière pendant toute la durée prévue."],v:["Le bas du dos doit rester plaqué en permanence : s'il se décolle, monte les jambes plus haut.","Ne cherche pas la grande amplitude, les petits battements sont plus efficaces et plus sûrs.","Fléchis légèrement les genoux si les lombaires tirent."],r:"Respire régulièrement et rapidement, sans bloquer."},
  a13:{d:"Allongé sur le dos, mains posées aux tempes, genoux fléchis et décollés du sol.",e:["Plaque le bas du dos et décolle les épaules du sol.","Amène le coude droit vers le genou gauche en tendant simultanément la jambe droite.","La rotation vient du buste, pas des bras : c'est l'épaule qui va chercher le genou.","Change de côté dans un mouvement de pédalage fluide.","Garde les épaules décollées pendant toute la série."],v:["Ne tire jamais sur la nuque avec les mains : elles ne servent qu'à accompagner la tête.","Si tu bouges seulement les coudes, les obliques ne travaillent pas : c'est le buste qui pivote.","Cadence lente et contrôlée plutôt que rapide."],r:"Souffle à chaque rotation, inspire pendant la transition."},
  a14:{d:"Allongé sur le dos, jambes tendues vers le plafond, bras tendus vers les pieds.",e:["Monte les jambes à la verticale et garde-les immobiles pendant tout l'exercice.","Plaque le bas du dos au sol.","Décolle les épaules et monte les mains vers les pieds.","Le mouvement est court : il vient de la contraction des abdominaux, pas de l'élan des bras.","Redescends les épaules sans les reposer complètement."],v:["Les jambes restent fixes : si elles se rapprochent du buste, tu triches.","Ne donne pas d'élan avec les bras.","Fléchis légèrement les genoux si l'arrière des cuisses tire trop."],r:"Souffle en montant, inspire en redescendant."},
  a15:{d:"Allongé sur le dos, bras tendus vers le plafond, genoux fléchis à 90° et décollés, tibias parallèles au sol.",e:["Plaque le bas du dos au sol : c'est la seule chose qui compte dans cet exercice.","Descends simultanément le bras droit derrière la tête et la jambe gauche vers le sol.","Va jusqu'à quelques centimètres du sol sans rien poser.","Reviens en position de départ, puis alterne les côtés.","Surveille en permanence le contact du bas du dos avec le sol."],v:["Dès que le bas du dos se décolle, réduis l'amplitude : c'est la règle absolue de cet exercice.","Mouvement lent et contrôlé, sans à-coup.","Le bassin ne doit ni tourner ni basculer."],r:"Souffle en tendant les membres, inspire en revenant."},
  c7:{d:"Debout, pieds écartés de la largeur des hanches, bras fléchis le long du corps.",e:["Cours sur place en ramenant alternativement les talons vers les fessiers.","Cherche à toucher les fesses avec le talon, aussi haut et aussi vite que possible.","Garde le buste droit, sans te pencher en avant.","Balance les bras naturellement le long du corps.","Maintiens la cadence pendant toute la durée prévue."],v:["Ne te penche pas en avant, c'est le réflexe qui apparaît avec la fatigue.","Reste sur la plante des pieds, sans écraser les talons au sol.","Exercice sans impact important : bon choix si tes articulations sont sensibles."],r:"Respire de façon rythmée et continue."},
  c8:{d:"Debout, pieds écartés de la largeur des épaules, genoux souples.",e:["Descends en squat jusqu'à mi-hauteur pour préparer l'impulsion.","Détends-toi vers le haut en poussant explosivement dans les jambes.","Amortis chaque réception sur la plante des pieds puis les talons, genoux fléchis.","Enchaîne directement le squat suivant, sans pause en position debout.","Tiens la cadence pendant toute la durée prévue."],v:["Ne retombe jamais jambes raides : l'amortissement genoux fléchis est non négociable.","Arrête la série dès que les réceptions deviennent bruyantes ou instables.","Le dos reste droit malgré la fatigue accumulée."],r:"Souffle à chaque impulsion, inspire pendant la descente."},
  c9:{d:"Genoux légèrement fléchis en position athlétique, pieds écartés de la largeur des hanches.",e:["Fléchis les genoux et abaisse le centre de gravité : reste bas pendant tout l'exercice.","Déplace-toi latéralement de trois ou quatre pas rapides d'un côté.","Reviens de la même façon dans l'autre sens.","Ne croise jamais les pieds pendant le déplacement.","Garde le buste droit et le regard devant."],v:["Se redresser entre les changements de direction annule l'intérêt de l'exercice : reste bas.","Ne croise pas les jambes, tu risquerais de trébucher.","Adapte l'amplitude à l'espace dont tu disposes."],r:"Respire de façon rythmée et continue."},
  c10:{d:"Debout en position de fente, un pied en avant, genoux fléchis, buste droit.",e:["Installe-toi en fente stable, genoux à environ 90°.","Saute verticalement en poussant dans les deux jambes.","Change de jambe en l'air, sans mouvement brusque du buste.","Retombe directement en fente de l'autre côté, en amortissant genoux souples.","Enchaîne sans temps mort pendant toute la durée prévue."],v:["Exercice exigeant en coordination et en impact : maîtrise la fente arrière classique avant.","Le genou avant reste aligné avec la cheville à chaque réception.","Arrête dès que la réception devient dure ou que le genou part vers l'intérieur."],r:"Souffle à l'impulsion, inspire pendant la réception."},
  c11:{d:"En position de planche bras tendus, mains sous les épaules, corps en ligne droite, pieds serrés.",e:["Verrouille le gainage : le haut du corps ne doit pas bouger de tout l'exercice.","Écarte les deux pieds d'un petit saut, au-delà de la largeur des hanches.","Ramène-les d'un second saut à la position serrée.","Le bassin reste à la même hauteur, il ne monte ni ne descend.","Garde une cadence régulière pendant toute la durée prévue."],v:["Le bassin qui rebondit à chaque saut est le défaut principal : ralentis la cadence.","Les épaules restent à l'aplomb des mains, sans reculer.","Impact sur les poignets : échauffe-les avant et arrête en cas de gêne."],r:"Respire de façon rythmée, sans bloquer."},
  c12:{d:"Debout, genoux légèrement fléchis, buste légèrement incliné vers l'avant.",e:["Prends appui sur une jambe, l'autre légèrement décollée.","Saute latéralement pour atterrir sur l'autre pied, en croisant légèrement la jambe libre derrière.","Amortis chaque réception sur une seule jambe, genou fléchi.","Reste bas entre les sauts, sans te redresser.","Enchaîne d'un côté à l'autre pendant toute la durée prévue."],v:["La réception sur une seule jambe demande du contrôle : commence par de petits sauts.","Le genou d'appui ne doit pas rentrer vers l'intérieur à la réception.","Arrête dès que l'équilibre devient instable."],r:"Respire de façon rythmée et continue."},
  p17:{d:"Debout face à un mur, mains posées à hauteur de poitrine, écartées de la largeur des épaules.",e:["Pose les mains à plat contre le mur, à hauteur de poitrine.","Recule les pieds d'un pas, corps en ligne droite inclinée.","Plie les coudes pour approcher la poitrine du mur, en gardant les coudes à environ 45°.","Va jusqu'à ce que la poitrine touche presque le mur.","Repousse en tendant les bras, sans casser au niveau des hanches."],v:["Plus tu reculuses les pieds, plus l'exercice devient difficile : c'est le seul réglage nécessaire.","Le corps reste une ligne droite, ne casse pas au bassin.","Version la plus accessible des pompes : idéale pour apprendre le geste avant de passer au sol."],r:"Inspire en descendant, souffle en repoussant."},
  p18:{d:"À genoux au sol, mains posées nettement plus larges que les épaules, chevilles croisées.",e:["Écarte les mains d'environ une fois et demie la largeur des épaules.","Aligne genoux, bassin et épaules, sans casser au niveau des hanches.","Descends la poitrine vers le sol en ouvrant les coudes à 45°.","Va jusqu'à quelques centimètres du sol.","Repousse en tendant les bras, en gardant la ligne du corps."],v:["La prise large accentue l'étirement des pectoraux mais réduit l'amplitude : c'est normal.","Ne casse pas au niveau des hanches.","Place un coussin sous les genoux s'ils sont sensibles."],r:"Inspire en descendant, souffle en repoussant."},
  p19:{d:"À genoux au sol en position de pompe, mains largeur d'épaules, corps aligné des genoux aux épaules.",e:["Installe-toi en position de pompe sur les genoux, corps gainé.","Descends jusqu'à mi-parcours, coudes fléchis à environ 90°.","Arrête-toi là et verrouille la position.","Garde les coudes près du corps et le bassin dans l'alignement.","Tiens la position immobile pendant toute la durée prévue."],v:["Le bassin qui s'affaisse est le défaut principal : arrête la série dès qu'il descend.","Ne descends pas jusqu'au sol, la mi-course est le point le plus difficile et donc le plus utile.","Le muscle travaille en continu, sans phase de repos : la durée sera courte, c'est normal."],r:"Respire régulièrement et sans blocage pendant tout le maintien."},
  p20:{d:"Debout dans un angle de mur ou dans un encadrement de porte, bras tendus sur les côtés à hauteur d'épaules, paumes à plat contre la paroi.",e:["Pose les paumes à plat, bras tendus à hauteur d'épaules.","Avance un pied pour stabiliser ta position.","Avance doucement le buste jusqu'à sentir l'étirement des pectoraux.","Ne va jamais au-delà d'un étirement confortable.","Repousse en ramenant les bras vers l'avant, en contractant la poitrine."],v:["Mouvement doux, sans à-coup : la position d'étirement de l'épaule ne supporte pas la brusquerie.","N'avance pas trop le buste, l'amplitude utile est modeste.","Arrête immédiatement en cas de pincement dans l'épaule."],r:"Inspire en avançant le buste, souffle en repoussant."},
  p21:{d:"Mains rapprochées sur une table ou un plan de travail, pieds reculés, corps en ligne inclinée.",e:["Rapproche les mains jusqu'à la largeur des épaules ou légèrement moins.","Vérifie la stabilité du support avant de t'appuyer.","Verrouille le gainage pour aligner talons, bassin et épaules.","Descends la poitrine vers les mains en gardant les coudes le long du corps.","Repousse en tendant les bras, sans casser au bassin."],v:["La hauteur du support permet de doser précisément la difficulté : commence haut.","Les coudes restent serrés, c'est ce qui cible les triceps.","Le corps forme une ligne droite, pas un V."],r:"Inspire en descendant, souffle en repoussant."},
  b19:{d:"Assis au bord d'une chaise stable, mains agrippées au bord de part et d'autre des hanches, genoux fléchis à 90°, pieds à plat au sol.",e:["Vérifie que la chaise ne peut pas glisser ni basculer.","Garde les genoux fléchis et les pieds à plat : cette position allège nettement la charge.","Avance les fesses dans le vide en restant près du bord.","Descends en fléchissant les coudes vers l'arrière, jusqu'à environ 90°.","Repousse en tendant les bras, épaules basses."],v:["Ne descends pas plus bas que 90° : au-delà, l'épaule est en contrainte forte.","Rapproche les pieds du corps pour alléger davantage, éloigne-les pour durcir.","Les épaules restent loin des oreilles."],r:"Inspire en descendant, souffle en repoussant."},
  b20:{d:"Debout face à un mur, mains rapprochées à hauteur de poitrine, pouces se touchant presque.",e:["Pose les mains à plat, rapprochées, à hauteur de poitrine.","Recule les pieds d'un pas, corps en ligne droite inclinée.","Plie les coudes en les gardant serrés contre les côtes.","Approche le front du mur, sans le toucher.","Repousse en tendant les bras."],v:["Les coudes qui s'écartent transfèrent le travail vers les pectoraux : garde-les serrés.","Recule les pieds pour durcir, rapproche-les pour alléger.","Version la plus accessible pour travailler les triceps sans matériel."],r:"Inspire en descendant, souffle en repoussant."},
  b21:{d:"À genoux devant une chaise, avant-bras posés sur l'assise, coudes fléchis.",e:["Pose les avant-bras à plat sur l'assise, coudes largeur d'épaules.","Recule les genoux pour incliner légèrement le buste.","Descends le buste en pliant uniquement les coudes.","Les coudes ne doivent ni s'écarter ni glisser sur l'assise.","Repousse en tendant les bras, sans bouger les épaules."],v:["Les coudes qui glissent sur l'assise annulent le mouvement : vérifie l'adhérence.","Recule les genoux pour durcir, rapproche-les pour alléger.","Place un coussin sous les genoux s'ils sont sensibles."],r:"Inspire en descendant, souffle en tendant."},
  b22:{d:"Debout, bras le long du corps, paumes tournées vers l'avant, poings fermés.",e:["Ferme les poings fermement : cette contraction volontaire remplace la charge.","Monte lentement les avant-bras en comptant quatre secondes.","Serre les poings au maximum pendant toute la montée.","Marque une contraction d'une seconde en position haute.","Redescends aussi lentement, en gardant la tension jusqu'en bas."],v:["Sans contraction volontaire des poings et des biceps, l'exercice est sans effet : tout repose sur ton engagement.","Les coudes restent collés aux côtes.","La lenteur est l'exercice : accélérer le rend inutile."],r:"Souffle en montant, inspire en redescendant."},
  e17:{d:"Debout face à un mur, mains posées un peu plus bas que les épaules, pieds reculés.",e:["Pose les mains à plat, légèrement en dessous du niveau des épaules.","Recule les pieds et penche le buste vers l'avant : c'est cette inclinaison qui charge les épaules.","Plie les coudes pour approcher le sommet du crâne du mur.","Va jusqu'à quelques centimètres du mur.","Repousse en tendant les bras, en gardant l'inclinaison du buste."],v:["Plus tu penches le buste vers l'avant, plus la charge passe des pectoraux aux épaules.","Recule les pieds pour durcir progressivement.","Version accessible du pike push-up : idéale pour préparer le travail vertical."],r:"Inspire en descendant, souffle en repoussant."},
  e18:{d:"Debout, bras le long du corps, épaules relâchées.",e:["Laisse les bras totalement détendus le long du corps.","Effectue de grands cercles avec les épaules seules, vers l'arrière.","Cherche l'amplitude maximale : monte, recule, descends, avance.","Serre les omoplates à chaque passage vers l'arrière.","Change de sens à la moitié de la série."],v:["Le mouvement vient des épaules, pas des bras : ceux-ci restent passifs.","Va lentement pour atteindre la véritable amplitude, la vitesse la réduit.","Excellent échauffement avant tout travail des épaules."],r:"Respire lentement et profondément pendant les rotations."},
  e19:{d:"En position de pompe bras tendus, mains sous les épaules, corps en ligne droite des talons à la tête.",e:["Place les mains exactement sous les épaules, bras tendus sans verrouiller.","Contracte le ventre et les fessiers pour verrouiller le bassin.","Pousse activement le sol pour écarter les omoplates.","Garde la nuque dans l'axe, regard légèrement en avant.","Tiens la position immobile pendant toute la durée prévue."],v:["Le bassin qui s'affaisse charge le bas du dos : arrête la série dès qu'il descend.","Ne laisse pas les épaules reculer derrière les mains.","Pose les genoux au sol plutôt que de tenir une position dégradée."],r:"Respire régulièrement et sans blocage."},
  e20:{d:"Debout, bras le long du corps, poings fermés, buste droit.",e:["Ferme les poings et contracte volontairement les épaules.","Monte les bras tendus sur les côtés en comptant cinq secondes.","Monte jusqu'à hauteur exacte des épaules, pas plus haut.","Marque une contraction d'une seconde en position haute.","Redescends en comptant cinq secondes, sans laisser les bras tomber."],v:["Toute l'efficacité repose sur la lenteur et la contraction volontaire : accélérer rend l'exercice inutile.","Ne monte pas au-dessus des épaules, le trapèze prendrait le relais.","Les épaules restent basses, loin des oreilles."],r:"Souffle pendant les cinq secondes de montée, inspire pendant la descente."},
  a16:{d:"Allongé sur le dos, mains sous les fesses, genoux fléchis, pieds décollés du sol.",e:["Glisse les mains sous les fesses pour plaquer le bas du dos.","Fléchis les genoux à environ 90° et décolle les pieds.","Ramène les genoux vers la poitrine en décollant légèrement le bassin.","Marque une brève contraction en position haute.","Redescends sans poser les pieds au sol, puis enchaîne."],v:["Le bas du dos reste en contact avec le sol pendant tout le mouvement.","Ne donne pas d'élan avec les jambes, le mouvement vient des abdominaux.","Version accessible du relevé de jambes : maîtrise-la avant de tendre les jambes."],r:"Souffle en ramenant les genoux, inspire en redescendant."},
  a17:{d:"En appui sur les avant-bras et les genoux, coudes sous les épaules, corps aligné des genoux aux épaules.",e:["Place les coudes exactement sous les épaules.","Pose les genoux au sol, écartés de la largeur des hanches.","Rentre le ventre et serre les fessiers pour aligner genoux, bassin et épaules.","Rentre légèrement le menton, nuque dans l'axe.","Tiens la position immobile pendant toute la durée prévue."],v:["Le bassin qui s'affaisse ou qui remonte casse l'alignement : c'est le seul point à surveiller.","Version accessible de la planche : passe à la version pieds tendus quand tu tiens confortablement une minute.","Place un tapis sous les genoux s'ils sont sensibles."],r:"Respire régulièrement, sans jamais tenir en apnée."},
  c13:{d:"Debout, pieds écartés de la largeur des hanches, bras libres le long du corps.",e:["Marche sur place en levant les genoux à hauteur de hanches.","Balance les bras naturellement en opposition avec les jambes.","Déroule bien le pied à chaque pose, du talon vers la pointe.","Garde le buste droit et le regard devant.","Maintiens un rythme soutenu mais confortable pendant toute la durée."],v:["Ne te penche pas en avant, le buste reste vertical.","Exercice sans aucun impact : parfait pour démarrer, récupérer entre deux séries, ou si tes articulations sont sensibles.","Monte les genoux plus haut pour augmenter l'intensité."],r:"Respire profondément et régulièrement."},
  c14:{d:"Debout, pieds serrés, bras le long du corps.",e:["Écarte une jambe sur le côté en posant la pointe du pied au sol.","Monte simultanément les bras au-dessus de la tête.","Ramène la jambe et les bras en position de départ.","Alterne avec l'autre jambe, à cadence régulière.","Les pieds ne quittent jamais complètement le sol."],v:["Le mouvement des bras doit rester complet malgré l'absence de saut : c'est lui qui fait monter le rythme cardiaque.","Version sans impact des jumping jacks : idéale si tes genoux ou tes chevilles sont sensibles.","Accélère la cadence pour augmenter l'intensité."],r:"Respire de façon rythmée et continue."},
  c15:{d:"Debout en position de garde, pieds décalés, genoux légèrement fléchis, poings fermés devant le visage.",e:["Place-toi en garde, un pied légèrement en avant, poings protégeant le visage.","Lance des coups de poing devant toi en alternant les bras.","Fais pivoter légèrement le buste et la hanche à chaque coup : la puissance vient des jambes.","Ramène toujours le poing en garde avant de lancer le suivant.","Reste mobile sur les appuis pendant toute la durée."],v:["Ne verrouille jamais complètement le coude en fin de coup, cela abîme l'articulation à la longue.","Garde les épaules basses malgré la fatigue.","Exercice sans impact au sol, mais qui fait monter le rythme cardiaque très vite."],r:"Souffle brièvement à chaque coup, sans bloquer la respiration."},
  c16:{d:"Debout, pieds écartés de la largeur des hanches, mains devant toi ou sur les hanches.",e:["Monte un genou vers la poitrine, de façon marquée et contrôlée.","Repose le pied complètement avant de monter l'autre genou.","Garde le dos droit et le ventre engagé.","Cherche la hauteur du genou plutôt que la vitesse.","Maintiens une cadence régulière pendant toute la durée prévue."],v:["Contrairement à la version rapide, chaque montée est marquée : cela limite l'essoufflement.","Ne te penche pas en arrière pour monter plus haut.","Bonne option pour l'échauffement ou une reprise en douceur."],r:"Respire régulièrement et profondément."},
  d19:{d:"Allongé sur le ventre, mains posées le long du corps, front au sol, jambes tendues.",e:["Laisse les bras le long du corps, paumes vers le sol.","Contracte le ventre et les fessiers pour protéger le bas du dos.","Décolle uniquement la poitrine de quelques centimètres, sans t'aider des bras.","L'amplitude est volontairement faible : c'est la contraction qui compte, pas la hauteur.","Redescends lentement et sans à-coup."],v:["Ne pousse pas sur les bras, ils restent passifs le long du corps.","Ne lève pas la tête vers le plafond, la nuque suit l'axe de la colonne.","Arrête l'amplitude dès qu'une gêne apparaît dans le bas du dos."],r:"Souffle en décollant la poitrine, inspire en redescendant."},
  d20:{d:"Allongé sur le ventre, bras tendus devant, une serviette tenue à deux mains écartées, front au sol.",e:["Tiens la serviette à deux mains, écartées d'environ la largeur des épaules.","Décolle les bras de quelques centimètres.","Tire sur la serviette vers l'extérieur tout en ramenant les coudes vers les hanches.","La tension de la serviette rend la contraction des omoplates beaucoup plus perceptible qu'à vide.","Retends les bras vers l'avant sans les reposer."],v:["Maintiens la tension sur la serviette pendant tout le mouvement, y compris au retour.","Ne décolle pas la poitrine, seuls les bras travaillent.","Cherche la contraction entre les omoplates, pas l'amplitude."],r:"Souffle en tirant les coudes en arrière, inspire en retendant."},
  a18:{d:"Allongé sur le côté, appui sur l'avant-bras, coude sous l'épaule, genoux fléchis et posés au sol.",e:["Place le coude exactement sous l'épaule.","Fléchis les genoux et pose-les au sol, l'un sur l'autre.","Décolle le bassin jusqu'à aligner épaule, hanche et genou.","L'appui sur les genoux réduit nettement le levier par rapport à la version jambes tendues.","Tiens la position sans laisser le bassin retomber."],v:["Le bassin qui s'affaisse est le signal d'arrêt de la série.","Les hanches restent empilées, le corps ne bascule pas vers l'avant.","Passe à la version jambes tendues quand tu tiens confortablement quarante secondes."],r:"Respire régulièrement, sans blocage."},
  c17:{d:"Debout, genoux légèrement fléchis en position athlétique, pieds écartés de la largeur des hanches.",e:["Fléchis les genoux et abaisse le centre de gravité.","Déplace-toi d'un pas sur le côté, puis reviens immédiatement.","Les deux pieds ne quittent jamais vraiment le sol : ils glissent plutôt qu'ils ne sautent.","Garde le buste droit et les bras actifs devant toi.","Maintiens un rythme régulier et soutenu pendant toute la durée."],v:["Reste bas pendant tout l'exercice : se redresser entre les pas réduit fortement l'intensité.","Sans impact articulaire : bonne option si tes genoux ou tes chevilles sont sensibles.","Accélère la cadence plutôt que d'agrandir les pas pour augmenter l'intensité."],r:"Respire de façon rythmée et continue."},
  b23:{d:"À genoux face au sol, mains posées largeur d'épaules, coudes serrés contre les côtes.",e:["Pose les genoux au sol et les mains largeur d'épaules devant toi.","Aligne genoux, bassin et épaules, sans casser au bassin.","Descends en pliant uniquement les coudes, avant-bras allant vers le sol.","Les coudes restent serrés contre les côtes, ils ne s'écartent pas.","Repousse en tendant les bras, sans bouger les épaules."],v:["La position à genoux allège considérablement la charge par rapport à la planche : c'est le bon point de départ.","Les coudes qui s'ouvrent déplacent le travail vers les pectoraux.","Place un coussin sous les genoux s'ils sont sensibles."],r:"Inspire en descendant, souffle en tendant."},
  j21:{d:"Debout sur une jambe, l'autre légèrement décollée derrière, un haltère dans la main opposée à la jambe d'appui.",e:["Fléchis très légèrement le genou d'appui et garde-le fixe à cet angle.","Bascule le buste vers l'avant en envoyant la jambe libre vers l'arrière, comme une balance.","L'haltère descend au ras de la jambe d'appui, jamais éloigné du corps.","Descends jusqu'à sentir l'étirement de l'ischio, en arrêtant dès que le dos veut s'arrondir.","Remonte en contractant le fessier de la jambe d'appui."],v:["Le bassin doit rester horizontal : s'il s'ouvre vers le côté, réduis l'amplitude.","Le dos ne s'arrondit jamais, c'est la limite absolue du mouvement.","Pose un doigt sur un mur pour l'équilibre plutôt que d'exécuter un geste chaotique."],r:"Inspire en descendant, souffle en remontant."},
  j22:{d:"Allongé sur le dos, genoux fléchis, talons posés sur une serviette sur un sol lisse, bassin décollé.",e:["Décolle le bassin et garde-le haut pendant tout l'exercice.","Fais glisser lentement les talons vers l'avant en tendant les jambes.","Va jusqu'à ce que les jambes soient presque tendues, sans poser le bassin.","Ramène les talons vers les fessiers en contractant l'arrière des cuisses.","C'est la phase de retour qui fait tout le travail : ramène lentement, sans à-coup."],v:["Le bassin qui retombe pendant le glissement annule l'exercice.","Teste le glissement de la serviette avant de charger le mouvement.","Réduis l'amplitude si des crampes apparaissent, fréquentes sur ce mouvement."],r:"Inspire en tendant les jambes, souffle en les ramenant."},
  j23:{d:"Debout au centre d'un élastique, les deux pieds dessus, l'autre extrémité passée derrière la nuque sur les trapèzes.",e:["Vérifie que l'élastique est bien calé sur le haut du dos, jamais sur les cervicales.","Fléchis très légèrement les genoux et garde-les fixes.","Bascule le bassin vers l'arrière et incline le buste vers l'avant, dos droit.","La résistance augmente à mesure que tu descends, exactement là où l'ischio s'étire.","Remonte en contractant les fessiers, sans cambrer en fin de mouvement."],v:["L'élastique ne doit jamais reposer sur la nuque, mais sur les trapèzes.","Arrête la descente dès que le bas du dos s'arrondit.","Commence avec une résistance faible : le bras de levier est important."],r:"Inspire en descendant, souffle en remontant."},
  j24:{d:"À genoux sur un tapis, chevilles bloquées sous un meuble lourd ou tenues par un partenaire, buste droit.",e:["Vérifie que le blocage des chevilles est parfaitement solide avant de te pencher.","Contracte fessiers et abdominaux pour aligner genoux, bassin et épaules.","Descends le buste vers l'avant le plus lentement possible, en résistant avec l'arrière des cuisses.","Place les mains devant toi pour amortir la fin de la descente.","Repousse au sol avec les mains pour revenir, l'ischio ne pouvant pas encore remonter seul."],v:["Exercice très exigeant : la descente doit rester contrôlée, sinon c'est une simple chute.","Ne casse jamais au niveau des hanches, le corps reste une ligne droite.","Les courbatures sont intenses après ce mouvement : commence par trois répétitions."],r:"Inspire pendant la descente, souffle en repoussant."},
  j25:{d:"Allongé sur le dos, un talon posé sur une chaise, l'autre jambe tendue vers le plafond, bras le long du corps.",e:["Vérifie la stabilité du support avant de commencer.","Plaque le bas du dos et contracte le ventre pour verrouiller le bassin.","Pousse dans le talon posé pour décoller le bassin.","Monte jusqu'à aligner épaules, hanche et genou d'appui, sans laisser le bassin s'incliner.","Redescends lentement sans poser complètement le bassin."],v:["Le bassin qui bascule du côté de la jambe levée est le défaut principal.","La surélévation augmente l'amplitude : ne cambre pas pour monter plus haut.","Reviens à la version deux jambes si tu ne tiens pas le bassin horizontal."],r:"Souffle en montant, inspire en redescendant."},
  j26:{d:"Debout, pieds écartés de la largeur des hanches, un balai ou un manche tenu verticalement dans le dos, en contact avec la nuque, le haut du dos et le sacrum.",e:["Maintiens les trois points de contact du bâton : nuque, omoplates, sacrum. Ils sont le contrôle de l'exercice.","Fléchis très légèrement les genoux et garde-les fixes à cet angle.","Bascule le bassin vers l'arrière en inclinant le buste, comme si tu poussais une porte avec les fesses.","Si l'un des trois contacts se perd, tu as arrondi ou cambré : remonte immédiatement.","Descends jusqu'à sentir l'étirement de l'arrière des cuisses, puis remonte en poussant le bassin vers l'avant."],v:["C'est l'exercice d'apprentissage du mouvement de charnière : maîtrise-le avant tout soulevé de terre.","Ce n'est pas un squat : les genoux ne se fléchissent presque pas.","Le bâton n'est pas décoratif, il remplace le regard d'un coach sur ta posture."],r:"Inspire en descendant, souffle en remontant."},
  j27:{d:"Allongé sur le dos, jambes tendues, talons posés au sol, pointes de pieds vers le plafond, bras le long du corps.",e:["Plaque le bas du dos au sol et contracte le ventre.","Pousse fort dans les talons pour décoller le bassin, jambes restant tendues.","Jambes tendues, ce sont les ischios et non les fessiers qui fournissent l'essentiel de l'effort.","Monte jusqu'à aligner épaules, hanches et talons, sans cambrer.","Redescends lentement sans poser complètement le bassin."],v:["Si tu sens surtout les fessiers, rapproche les talons : tu es en pont fessier classique.","Ne cambre pas pour monter plus haut, arrête-toi à l'alignement.","Des crampes à l'arrière des cuisses sont fréquentes au début : réduis l'amplitude."],r:"Souffle en montant, inspire en redescendant."},
  j28:{d:"Debout, pieds écartés de la largeur des hanches, genoux très légèrement déverrouillés, mains posées à plat sur l'avant des cuisses.",e:["Verrouille le dos droit et sors la poitrine avant de bouger.","Bascule le bassin vers l'arrière en faisant glisser les mains le long des cuisses.","Les genoux restent quasiment fixes : tout le mouvement vient de la hanche.","Descends jusqu'à sentir un étirement franc à l'arrière des cuisses, généralement vers le genou.","Remonte en contractant les fessiers et en poussant le bassin vers l'avant."],v:["Le dos qui s'arrondit marque la limite d'amplitude du jour : ne va jamais au-delà.","Les mains glissant sur les cuisses donnent un repère fiable de la trajectoire.","Ne cherche pas à toucher le sol, l'amplitude dépend entièrement de ta souplesse."],r:"Inspire en descendant, souffle en remontant."},
  j29:{d:"Debout face à un point d'ancrage bas, un élastique fixé à la cheville, une main en appui sur un mur pour l'équilibre.",e:["Vérifie la solidité du point d'ancrage et la fixation à la cheville.","Garde la cuisse verticale et immobile : seul le genou se plie.","Ramène le talon vers la fesse contre la résistance de l'élastique.","Marque une contraction d'une seconde en position haute.","Redescends lentement en résistant, sans laisser l'élastique ramener la jambe."],v:["La cuisse qui part vers l'arrière transfère le travail sur le fessier : garde-la verticale.","Ne cambre pas le bas du dos pour gagner en amplitude.","Le retour contrôlé compte autant que la flexion."],r:"Souffle en fléchissant, inspire en redescendant."},
  j30:{d:"Debout au centre d'un élastique, les deux pieds dessus, une extrémité dans chaque main devant les cuisses, genoux légèrement fléchis.",e:["Vérifie que l'élastique est bien bloqué sous les deux pieds.","Verrouille le dos droit et sors la poitrine.","Bascule le bassin vers l'arrière et descends les mains le long des jambes.","La résistance augmente à la remontée, exactement là où les ischios sont les plus forts.","Remonte en contractant les fessiers, sans cambrer en fin de mouvement."],v:["Le dos ne s'arrondit jamais : arrête la descente avant.","Garde les mains au contact des jambes, l'élastique tire vers l'avant.","Vérifie l'état de l'élastique avant chaque séance."],r:"Inspire en descendant, souffle en remontant."},
  j31:{d:"Debout sur une jambe, l'autre pied légèrement décollé derrière, mains posées derrière la tête, coudes ouverts.",e:["Fléchis légèrement le genou d'appui et garde-le fixe.","Bascule le buste vers l'avant en envoyant la jambe libre vers l'arrière, en balance.","Cherche l'alignement tête-dos-jambe libre sur une même ligne horizontale.","Descends jusqu'à sentir l'étirement de l'ischio d'appui, sans arrondir le dos.","Remonte en contractant le fessier de la jambe d'appui."],v:["Le bassin doit rester horizontal : s'il s'ouvre sur le côté, réduis l'amplitude.","Pose un doigt sur un mur pour l'équilibre plutôt que de te tortiller.","Termine toutes les répétitions d'un côté avant de changer."],r:"Inspire en descendant, souffle en remontant."},
  a19:{d:"Assis au sol, mains posées derrière toi en appui, genoux fléchis, pieds légèrement décollés, buste incliné en arrière.",e:["Recule légèrement le buste et décolle les pieds de quelques centimètres.","Ramène simultanément les genoux vers la poitrine et le buste vers les genoux.","Le mouvement se ferme des deux côtés à la fois : c'est ce qui le rend polyarticulaire.","Marque une contraction d'une seconde en position groupée.","Rouvre lentement sans poser les pieds ni le dos complètement."],v:["Ne pose pas les pieds entre les répétitions, la tension doit rester continue.","Le bas du dos ne doit pas claquer au sol à l'ouverture : contrôle jusqu'au bout.","Garde les mains en appui léger, elles ne doivent pas tirer le buste."],r:"Souffle en groupant, inspire en ouvrant."},
  a20:{d:"En position de planche bras tendus, mains sous les épaules, pieds écartés un peu plus que la largeur des hanches.",e:["Écarte les pieds : plus la base est large, plus le bassin reste stable.","Verrouille le gainage et contracte les fessiers.","Décolle une main pour venir toucher l'épaule opposée.","Le bassin ne doit pas tourner d'un millimètre : c'est là tout l'exercice.","Repose la main et alterne, à cadence lente."],v:["Le bassin qui bascule à chaque touche annule le travail : ralentis ou écarte davantage les pieds.","Ne décale pas les pieds pour compenser.","Mieux vaut six touches parfaitement stables que vingt désordonnées."],r:"Souffle à chaque touche, inspire au retour de la main."},
  a21:{d:"À quatre pattes, mains sous les épaules, genoux sous les hanches et décollés de quelques centimètres, dos plat.",e:["Décolle les genoux de trois ou quatre centimètres seulement et maintiens cette hauteur.","Avance simultanément la main droite et le pied gauche d'un petit pas.","Enchaîne avec la main gauche et le pied droit.","Le bassin reste bas et immobile : il ne monte pas et ne bascule pas.","Avance quelques pas puis recule de la même façon."],v:["Les genoux qui remontent transforment l'exercice en simple déplacement à quatre pattes.","Fais de très petits pas : l'amplitude fait perdre la stabilité.","Garde le dos plat, sans creuser ni arrondir."],r:"Respire régulièrement pendant tout le déplacement, sans bloquer."},
  a22:{d:"Allongé sur le dos, genoux fléchis, pieds à plat, un haltère tenu à deux mains contre la poitrine.",e:["Plaque le bas du dos au sol et serre l'haltère contre le sternum.","Enroule le haut du dos pour décoller les épaules de quelques centimètres.","La charge sur la poitrine augmente la résistance sans allonger l'amplitude.","Marque une contraction d'une seconde en position haute.","Redescends lentement sans reposer complètement la tête."],v:["Ne laisse pas l'haltère glisser vers le ventre : il perdrait tout effet de levier.","L'amplitude reste courte, comme un crunch classique.","Commence léger : quelques kilos suffisent à rendre l'exercice difficile."],r:"Souffle en montant, inspire en redescendant."},
  a23:{d:"Assis au sol, genoux fléchis, buste incliné à 45° vers l'arrière, un haltère tenu à deux mains devant la poitrine.",e:["Redresse le dos malgré l'inclinaison : il ne doit jamais s'arrondir.","Décolle légèrement les pieds si ton niveau le permet.","Pivote le buste d'un côté en amenant l'haltère vers la hanche.","La rotation vient du tronc, pas des bras : épaules et haltère tournent ensemble.","Reviens au centre puis pivote de l'autre côté."],v:["Le dos arrondi est le défaut principal : redresse-toi même si l'exercice devient plus dur.","Ne balance pas l'haltère par élan, le mouvement reste contrôlé.","Pose les pieds au sol pour alléger."],r:"Souffle à chaque rotation, inspire au retour au centre."},
  a24:{d:"Debout, pieds écartés de la largeur des hanches, un haltère dans une main le long du corps, l'autre main sur la nuque.",e:["Garde le buste strictement dans le plan latéral : ni rotation, ni inclinaison vers l'avant.","Descends l'haltère le long de la cuisse en fléchissant le buste sur le côté.","Va jusqu'à sentir l'étirement de l'oblique opposé.","Remonte en contractant le côté chargé.","Termine toutes les répétitions d'un côté avant de changer."],v:["Ne tiens pas un haltère dans chaque main : ils s'équilibreraient et l'exercice perdrait tout intérêt.","Ne te penche pas en avant, le mouvement est strictement latéral.","Charge modérée : les obliques répondent mieux au contrôle qu'au poids."],r:"Souffle en remontant, inspire en descendant."},
  a25:{d:"Debout de profil par rapport à un élastique fixé à hauteur de poitrine, les deux mains jointes sur la poignée contre le sternum.",e:["Écarte-toi du point d'ancrage jusqu'à sentir une tension franche.","Écarte les pieds et contracte le ventre pour verrouiller le tronc.","Tends les bras devant toi, à l'horizontale.","L'élastique cherche à te faire pivoter : tout l'exercice consiste à résister sans bouger.","Reviens lentement à la poitrine, puis change de côté à la série suivante."],v:["Si ton buste tourne, réduis la tension : l'objectif est l'immobilité, pas l'effort de poussée.","Les hanches restent face à l'avant, elles ne suivent pas les bras.","Excellent travail du gainage anti-rotation, rarement sollicité autrement."],r:"Respire régulièrement sans bloquer, malgré la tension."},
  a26:{d:"À genoux face à une poulie haute, une corde tenue à deux mains de part et d'autre du visage.",e:["Cale les mains contre les tempes et garde-les fixes pendant tout le mouvement.","Verrouille les hanches : elles ne doivent pas reculer.","Enroule le haut du dos vers le sol en rapprochant les coudes des cuisses.","Marque une contraction franche en position enroulée.","Reviens lentement en déroulant vertèbre par vertèbre."],v:["Ne tire pas avec les bras : ils ne servent qu'à tenir la corde.","Si les hanches basculent vers l'arrière, la charge est trop lourde.","Le mouvement est un enroulement du buste, pas une flexion de hanche."],r:"Souffle en enroulant, inspire en revenant."},
  a27:{d:"Allongé sur le dos, mains sous les fesses, un haltère léger serré entre les pieds ou les chevilles.",e:["Vérifie que l'haltère est bien calé avant de décoller les jambes.","Glisse les mains sous les fesses pour plaquer le bas du dos.","Monte les jambes tendues jusqu'à la verticale.","Redescends lentement et arrête-toi dès que le bas du dos veut se décoller.","Ne repose jamais les talons entre les répétitions."],v:["Le bas du dos qui se creuse est le signal d'arrêt : réduis l'amplitude basse.","Utilise un haltère très léger, deux ou trois kilos suffisent.","Fléchis les genoux si la version tendue est trop exigeante."],r:"Souffle en montant, inspire en redescendant."},
  c18:{d:"Debout, pieds écartés de la largeur des épaules, un haltère dans chaque main posé sur les épaules, coudes vers l'avant.",e:["Descends en squat complet en gardant les haltères stables sur les épaules.","Remonte en poussant dans les talons.","Enchaîne sans temps mort par une poussée des haltères au-dessus de la tête.","L'élan des jambes lance la poussée : c'est ce qui rend le mouvement si essoufflant.","Redescends les haltères aux épaules et enchaîne le squat suivant."],v:["Ne cambre pas le bas du dos au moment de la poussée, garde les côtes basses.","Charge légère : c'est un exercice de souffle, pas de force.","Arrête la série dès que le squat perd sa qualité."],r:"Souffle à la poussée vers le haut, inspire pendant la descente."},
  c19:{d:"Debout, pieds un peu plus larges que les épaules, un haltère tenu à deux mains devant le bassin, bras tendus.",e:["Bascule le bassin vers l'arrière et laisse l'haltère passer entre les jambes, dos droit.","Projette le bassin vers l'avant avec force pour lancer l'haltère à hauteur de poitrine.","Ce sont les hanches qui propulsent, jamais les bras : ils ne font qu'accompagner.","Laisse l'haltère redescendre en contrôlant, en rebasculant le bassin.","Enchaîne à cadence régulière."],v:["Ne squatte pas : le mouvement est une charnière de hanche, les genoux bougent peu.","Le dos ne s'arrondit jamais, c'est la faute la plus dangereuse ici.","Ne monte pas l'haltère plus haut que la poitrine."],r:"Souffle à la projection, inspire pendant la descente."},
  c20:{d:"Debout, un haltère lourd dans chaque main le long du corps, épaules basses et poitrine ouverte.",e:["Serre fermement les poignées et abaisse activement les épaules.","Contracte le ventre pour verrouiller le tronc.","Marche à pas réguliers sur la distance ou la durée prévue.","Le buste reste droit : ne te penche ni en avant ni sur le côté.","Repose les haltères en fléchissant les jambes, pas le dos."],v:["Si tu t'inclines d'un côté, les charges sont trop lourdes ou déséquilibrées.","Les épaules ne montent pas vers les oreilles malgré la fatigue.","Exercice très efficace pour la poigne et le gainage, souvent négligé."],r:"Respire régulièrement, sans bloquer sous la charge."},
  c21:{d:"Un élastique fixé derrière toi à hauteur de bassin, passé autour de la taille, en position de course légèrement penchée vers l'avant.",e:["Avance jusqu'à sentir une tension franche de l'élastique.","Penche légèrement le buste vers l'avant, comme en départ de sprint.","Cours sur place en montant les genoux, contre la résistance.","L'élastique tire vers l'arrière : chaque appui demande une poussée réelle.","Garde une cadence soutenue pendant toute la durée prévue."],v:["Vérifie l'ancrage avant de te lancer : une rupture en tension projetterait vers l'avant.","Ne te penche pas excessivement, le buste reste gainé.","Reste sur la plante des pieds."],r:"Respire de façon rythmée et continue."},
  c22:{d:"Debout sur le tapis, pince de sécurité attachée au vêtement, mains libres.",e:["Attache toujours la pince d'arrêt d'urgence avant de démarrer.","Commence par trois minutes de marche pour échauffer les articulations.","Augmente progressivement jusqu'à une allure que tu peux tenir sans t'essouffler complètement.","Garde le buste droit et le regard devant, sans t'agripper aux barres.","Termine par deux minutes de marche lente pour faire redescendre le rythme cardiaque."],v:["S'agripper aux barres allège le corps et fausse totalement la dépense.","Ne regarde pas tes pieds : cela déséquilibre et tasse la nuque.","Une légère pente rend l'effort plus efficace et moins traumatisant qu'une vitesse élevée."],r:"Respire profondément et régulièrement."},
  c23:{d:"Debout sur les pédales, mains sur les poignées mobiles, buste droit.",e:["Règle la résistance pour pouvoir tenir un rythme régulier sans à-coups.","Pousse avec les jambes et tire avec les bras en alternance : tout le corps travaille.","Garde le buste droit, sans t'affaisser sur les poignées.","Maintiens une cadence constante plutôt que des accélérations brutales.","Termine par deux minutes à faible résistance."],v:["Ne t'appuie pas sur les poignées fixes : cela supprime le travail du haut du corps.","Les talons restent en contact avec les pédales.","Sans impact articulaire : bonne option si tes genoux sont sensibles."],r:"Respire profondément et régulièrement."},
  f19:{d:"Assis dans la machine, dos calé contre le dossier, coussin posé sur le bassin, pieds à plat écartés de la largeur des hanches.",e:["Règle le coussin sur le pli de la hanche, jamais sur le ventre.","Pousse dans les talons pour monter le bassin jusqu'à l'alignement du buste.","Serre les fessiers une seconde complète en position haute.","Rentre légèrement le menton pour éviter de cambrer.","Redescends lentement sans laisser la charge reposer entièrement."],v:["Ne cherche pas à monter plus haut que l'alignement : tu cambrerais au lieu de contracter.","Les genoux restent écartés, ils ne rentrent pas vers l'intérieur.","Garde les talons ancrés au sol."],r:"Souffle en montant, inspire en redescendant."},
  f20:{d:"Debout, un élastique passé autour des chevilles, une main en appui sur un mur, poids sur la jambe d'appui.",e:["Contracte le ventre pour éviter de compenser avec le buste.","Écarte une jambe sur le côté contre la résistance, jambe tendue.","L'amplitude est faible : arrête-toi dès que le bassin veut basculer.","Marque une contraction d'une seconde en position ouverte.","Reviens lentement sans laisser l'élastique ramener la jambe."],v:["Ne te penche pas du côté opposé pour gagner en amplitude, c'est le défaut principal.","La pointe de pied reste dirigée vers l'avant, jamais vers le plafond.","Le retour contrôlé compte autant que l'ouverture."],r:"Souffle en écartant, inspire au retour."},
  f21:{d:"Debout face à la machine, une sangle fixée à la cheville, mains en appui sur le châssis.",e:["Recule légèrement pour mettre la poulie en tension dès le départ.","Contracte le ventre et garde le buste droit.","Tends la jambe vers l'arrière, genou légèrement fléchi.","Arrête-toi dès que le bassin veut basculer : l'amplitude utile est modeste.","Reviens lentement en résistant à la charge."],v:["Ne cambre pas le bas du dos pour monter plus haut, c'est le défaut le plus fréquent.","Le buste reste vertical, ne te penche pas vers l'avant.","Le bassin reste de face pendant tout le mouvement."],r:"Souffle en tendant la jambe, inspire au retour."},
  p22:{d:"Debout entre deux poulies hautes, une poignée dans chaque main, bras écartés et coudes légèrement fléchis, un pied en avant.",e:["Avance un pied pour stabiliser la position et garde le buste légèrement penché.","Conserve la même flexion de coude du début à la fin du mouvement.","Ramène les mains devant toi en décrivant un arc de cercle.","Croise légèrement les poignets en fin de mouvement pour accentuer la contraction.","Reviens lentement en laissant les pectoraux s'étirer, sans forcer."],v:["Si tu plies et tends les coudes, ce n'est plus un écarté mais un développé.","Ne recule pas les mains au-delà du plan du buste.","Charge modérée : la position d'étirement met l'épaule en tension."],r:"Souffle en ramenant, inspire en écartant."},
  p23:{d:"Allongé sur un banc incliné à 30°, un haltère dans chaque main à hauteur de poitrine, pieds à plat au sol.",e:["Choisis une inclinaison modérée : au-delà de 45°, ce sont les épaules qui prennent le relais.","Plaque le bas du dos et serre les omoplates contre le banc.","Pousse les haltères vers le haut en les rapprochant légèrement.","Ne verrouille pas les coudes en position haute.","Redescends jusqu'à ce que les coudes arrivent au niveau du buste."],v:["Ne descends pas les coudes plus bas que le buste : l'épaule serait en position vulnérable.","Les omoplates restent serrées pendant tout le mouvement.","Cette variante cible le haut des pectoraux, souvent en retard."],r:"Inspire en descendant, souffle en poussant."},
  e21:{d:"Debout, un haltère dans chaque main devant les cuisses, paumes vers le corps, coudes légèrement fléchis.",e:["Choisis une charge légère : le faisceau antérieur est un petit muscle.","Monte un bras devant toi, coude légèrement fléchi, jusqu'à hauteur d'épaule.","Arrête-toi à l'horizontale, pas plus haut.","Redescends lentement pendant que l'autre bras monte, en alternance.","Le buste reste strictement immobile."],v:["Le balancement du buste pour lancer la charge annule tout le travail.","Ne monte pas au-dessus de l'horizontale, le trapèze prendrait le relais.","Les épaules restent basses, loin des oreilles."],r:"Souffle en montant, inspire en redescendant."},
  e22:{d:"Buste penché vers l'avant à environ 45°, dos droit, un haltère dans chaque main sous la poitrine, coudes légèrement fléchis.",e:["Verrouille le buste penché et le dos plat : cette position ne bouge plus.","Écarte les bras sur les côtés en menant par les coudes.","Monte jusqu'à ce que les bras soient à hauteur du dos, sans aller plus haut.","Serre les omoplates en fin de mouvement.","Redescends lentement en contrôlant."],v:["Le buste qui se redresse pour aider est le défaut principal.","Charge très légère : ce faisceau est petit et souvent faible.","Ne tire pas les coudes vers les hanches, ce serait un rowing."],r:"Souffle en écartant, inspire au retour."},
  d21:{d:"Debout, un haltère dans chaque main le long du corps, bras tendus, épaules relâchées.",e:["Garde les bras complètement tendus : ils ne servent qu'à porter la charge.","Hausse les épaules vers les oreilles, le plus haut possible.","Marque une contraction d'une seconde en position haute.","Redescends lentement en laissant les épaules s'étirer vers le bas.","Ne fais jamais de rotation des épaules sous charge."],v:["Les rotations d'épaules avec des haltères lourds sollicitent l'articulation de façon risquée : le mouvement est strictement vertical.","Ne plie pas les coudes, cela transformerait l'exercice en tirage.","Le cou reste détendu, ne le rentre pas dans les épaules."],r:"Souffle en montant, inspire en redescendant."},
  j32:{d:"Assis dans la presse inclinée, dos et bassin plaqués, pieds à plat au milieu du plateau, écartés de la largeur des hanches.",e:["Place les pieds au milieu du plateau : trop bas, les genoux souffrent ; trop haut, ce sont les fessiers qui travaillent.","Déverrouille les sécurités et descends en contrôlant jusqu'à ce que les genoux forment un angle droit.","Le bas du dos ne doit jamais se décoller du dossier : c'est lui qui limite l'amplitude.","Repousse en poussant dans les talons, sans verrouiller les genoux en haut.","Enchaîne sans laisser la charge reposer sur les butées."],v:["Ne verrouille jamais les genoux en extension : toute la charge passerait dans l'articulation.","Si le bassin bascule en bas de course, réduis l'amplitude, ce sont tes lombaires qui encaissent.","Ne pose pas les mains sur les genoux pour t'aider."],r:"Souffle en poussant, inspire à la descente."},
  j33:{d:"Épaules calées sous les coussins, dos plaqué au dossier incliné, pieds au milieu du plateau, largeur des hanches.",e:["Cale bien les épaules et vérifie que tout le dos touche le dossier.","Déverrouille les sécurités et descends jusqu'à ce que les cuisses soient parallèles au plateau.","Le dossier guide la trajectoire : tu peux te concentrer entièrement sur les quadriceps.","Pousse dans les talons pour remonter, sans verrouiller les genoux.","Garde les genoux dans l'axe des pieds pendant toute la remontée."],v:["Les genoux qui rentrent vers l'intérieur sont le défaut principal : pousse-les activement vers l'extérieur.","Ne décolle jamais les talons du plateau.","Charge progressive : la machine permet de charger lourd sans que le corps ne prévienne."],r:"Souffle en remontant, inspire à la descente."},
  j34:{d:"Allongé sur le ventre, bassin plaqué au banc, rouleau posé juste au-dessus des talons.",e:["Règle le rouleau au-dessus du talon d'Achille, jamais sur le mollet.","Agrippe les poignées et plaque fermement le bassin sur le banc.","Fléchis les genoux en amenant les talons vers les fessiers.","Marque une contraction d'une seconde en position haute.","Redescends lentement sans laisser la charge tomber."],v:["Le bassin qui se décolle est le signe d'une charge trop lourde.","Ne donne pas de coup de reins pour lancer le mouvement.","Garde les pointes de pieds relâchées pour limiter les crampes."],r:"Souffle en fléchissant, inspire en redescendant."},
  j35:{d:"Barre guidée posée sur le haut du dos, pieds légèrement avancés par rapport à la barre, largeur des épaules.",e:["Avance les pieds de vingt centimètres environ : la barre étant guidée, cette position protège les genoux.","Déverrouille la barre en la faisant pivoter, puis descends en fléchissant les genoux.","Va jusqu'à ce que les cuisses soient parallèles au sol.","La trajectoire étant fixe, concentre-toi sur la profondeur et la vitesse.","Remonte en poussant dans les talons, sans verrouiller les genoux."],v:["Ne place pas les pieds sous la barre : la trajectoire guidée forcerait les genoux vers l'avant.","Le dos reste plaqué et droit, sans arrondi en bas de course.","Vérifie toujours que les crochets de sécurité sont réglés avant de charger."],r:"Souffle en remontant, inspire à la descente."},
  j36:{d:"Assis dans la machine, dos au dossier, cuisses écartées contre les coussins intérieurs.",e:["Règle l'écartement de départ pour sentir un étirement franc mais confortable.","Serre les cuisses l'une vers l'autre en poussant contre les coussins.","Marque une contraction d'une seconde en position fermée.","Reviens lentement en résistant, sans laisser la charge revenir d'un coup.","Arrête-toi avant l'étirement maximal pour garder la tension."],v:["Ne force jamais l'écartement de départ : les adducteurs se déchirent facilement.","Le dos reste au dossier, ne te penche pas en avant.","Le retour contrôlé compte autant que la fermeture."],r:"Souffle en fermant, inspire au retour."},
  j37:{d:"Debout dans la machine, épaules sous les coussins, avant des pieds sur la marche, talons dans le vide.",e:["Règle les coussins pour que les jambes soient tendues sans être verrouillées.","Laisse les talons descendre sous le niveau de la marche pour étirer complètement.","Monte le plus haut possible sur la pointe des pieds.","Marque une contraction franche d'une seconde en haut.","Redescends lentement en comptant trois secondes."],v:["Rebondir en bas de course annule tout l'exercice : la lenteur est essentielle.","Les genoux restent tendus mais non verrouillés.","Amplitude complète : de l'étirement maximal à la contraction maximale."],r:"Souffle en montant, inspire en redescendant."},
  j38:{d:"Assis, coussins posés sur le bas des cuisses près des genoux, avant des pieds sur la marche.",e:["Place les coussins près des genoux, jamais sur le milieu des cuisses.","Genoux fléchis à 90°, cette position cible le soléaire plutôt que le jumeau.","Laisse les talons descendre pour étirer, puis monte sur la pointe.","Marque une contraction d'une seconde en haut.","Redescends lentement, sans rebond."],v:["Cette variante complète la version debout : les deux muscles du mollet ne travaillent pas au même angle.","Ne rebondis pas en bas, tu solliciterais le tendon d'Achille.","Amplitude complète à chaque répétition."],r:"Souffle en montant, inspire en redescendant."},
  j39:{d:"Assis dans la presse, un seul pied au milieu du plateau, l'autre jambe posée sur le côté.",e:["Place le pied au centre du plateau pour éviter que la charge ne parte de travers.","Réduis la charge de plus de la moitié par rapport à la version à deux jambes.","Descends en contrôlant jusqu'à l'angle droit du genou.","Travailler une jambe à la fois révèle et corrige les déséquilibres de force.","Repousse dans le talon, puis termine toutes les répétitions avant de changer."],v:["Le bassin ne doit pas se décaler sur le côté : signe que la charge est trop lourde.","Le genou reste dans l'axe du pied.","Commence toujours par le côté le plus faible et aligne l'autre sur lui."],r:"Souffle en poussant, inspire à la descente."},
  j40:{d:"Assis dans la machine, une seule cheville derrière le rouleau, l'autre jambe pendante.",e:["Aligne le genou travaillé avec l'axe de rotation de la machine.","Tends la jambe jusqu'à l'extension complète.","Marque une contraction d'une seconde, cuisse fermement serrée.","Redescends en comptant trois secondes : c'est la phase la plus efficace.","Termine toutes les répétitions avant de changer de côté."],v:["Ne donne pas d'élan avec le buste, tiens les poignées latérales.","Les fesses restent sur le siège, sans décollement.","Réduis nettement la charge par rapport à la version à deux jambes."],r:"Souffle en tendant, inspire en redescendant."},
  f22:{d:"Debout de profil par rapport à une poulie basse, sangle fixée à la cheville extérieure, main en appui sur le châssis.",e:["Recule pour mettre la poulie en tension dès la position de départ.","Contracte le ventre et garde le buste strictement vertical.","Écarte la jambe sur le côté, tendue, contre la résistance.","L'amplitude utile est faible : arrête-toi dès que le bassin veut basculer.","Reviens lentement sans laisser la charge ramener la jambe."],v:["Ne te penche pas du côté opposé pour gagner en amplitude, c'est le défaut principal.","La pointe de pied reste dirigée vers l'avant.","Charge légère : le moyen fessier répond au contrôle, pas au poids."],r:"Souffle en écartant, inspire au retour."},
  f23:{d:"Assis dans la presse, pieds placés haut sur le plateau et écartés un peu plus que les épaules.",e:["Monte les pieds vers le haut du plateau : ce simple réglage transfère le travail des quadriceps vers les fessiers.","Écarte les pieds et ouvre légèrement les pointes vers l'extérieur.","Descends jusqu'à l'angle droit du genou, sans que le bassin ne décolle.","Repousse en poussant fort dans les talons.","Serre les fessiers en fin d'extension, sans verrouiller les genoux."],v:["Si le bas du dos se décolle en bas de course, réduis l'amplitude immédiatement.","Les genoux suivent l'axe des pointes de pieds.","Ne pose jamais les pieds tout en haut du plateau au point que les talons dépassent."],r:"Souffle en poussant, inspire à la descente."},
  f24:{d:"Installé sur le banc à lombaires, bassin appuyé sur le coussin, chevilles bloquées, buste penché vers l'avant.",e:["Règle le coussin pour qu'il soit sous les hanches, ce qui permet la flexion du bassin.","Arrondis légèrement le haut du dos et rentre le menton : cette position cible les fessiers plutôt que les lombaires.","Descends le buste jusqu'à sentir l'étirement de l'arrière des cuisses.","Remonte en contractant les fessiers, jusqu'à l'alignement du corps.","Ne monte jamais au-delà de l'alignement."],v:["Monter au-delà de l'horizontale met les lombaires en hyperextension : c'est la faute à éviter.","Sans l'arrondi volontaire du haut du dos, ce sont les lombaires qui prennent tout le travail.","Commence sans charge avant d'ajouter un poids."],r:"Souffle en remontant, inspire à la descente."},
  f25:{d:"Barre guidée sur le haut du dos, pieds nettement avancés par rapport à la barre, largeur des épaules.",e:["Avance les pieds de trente à quarante centimètres devant la barre.","Ce décalage, impossible avec une barre libre, oriente le travail vers les fessiers.","Descends en poussant le bassin vers l'arrière, dos plaqué au dossier de la barre.","Va jusqu'à ce que les cuisses passent la parallèle si ta mobilité le permet.","Remonte en poussant dans les talons et en serrant les fessiers."],v:["Les talons ne doivent jamais se décoller : s'ils le font, avance moins les pieds.","Les genoux ne dépassent pas les pointes de pieds dans cette position.","Vérifie les crochets de sécurité avant chaque série."],r:"Souffle en remontant, inspire à la descente."},
  f26:{d:"Face à une poulie basse, sangle à la cheville, buste légèrement penché vers l'avant, mains sur le châssis.",e:["Contracte le ventre pour verrouiller le bassin avant de bouger.","Tends la jambe vers l'arrière, genou légèrement fléchi.","Cherche la contraction du fessier plutôt que la hauteur du pied.","Marque une pause d'une seconde en fin d'extension.","Reviens lentement en résistant à la charge."],v:["Ne cambre pas le bas du dos pour monter plus haut : l'amplitude utile est courte.","Le bassin reste face à l'avant, sans rotation.","Le buste ne se relève pas pour accompagner le mouvement."],r:"Souffle en tendant la jambe, inspire au retour."},
  f27:{d:"En appui sur les avant-bras et un genou, l'autre pied posé sur la plateforme de la machine.",e:["Règle la hauteur des appuis pour que le dos reste plat, sans cambrure.","Cale le pied bien à plat sur la plateforme.","Pousse la plateforme vers l'arrière et le haut en tendant la hanche.","Le guidage de la machine permet de charger le fessier sans devoir stabiliser tout le corps.","Reviens lentement sans laisser la charge reposer entre les répétitions."],v:["Ne cambre pas le bas du dos en fin de poussée, c'est le fessier qui doit finir le mouvement.","Garde le regard vers le sol pour ne pas casser la nuque.","Termine toutes les répétitions d'un côté avant de changer."],r:"Souffle en poussant, inspire au retour."},
  d22:{d:"Assis à la machine, cuisses bloquées sous les coussins, poignée en V tenue à deux mains.",e:["Règle les coussins pour que les cuisses soient fermement maintenues.","Redresse le buste et ouvre la poitrine, très légèrement incliné en arrière.","Abaisse d'abord les omoplates, avant même de plier les bras.","Tire la poignée vers le haut de la poitrine, coudes serrés le long du corps.","Remonte lentement en laissant les omoplates s'écarter."],v:["La prise serrée cible la partie basse du grand dorsal : la trajectoire vers la poitrine est essentielle.","Ne donne pas d'élan avec le buste, l'inclinaison reste stable.","Le retour contrôlé compte autant que la traction."],r:"Souffle en tirant, inspire en remontant."},
  d23:{d:"Assis à la machine, poitrine calée contre le coussin, poignées tenues bras tendus.",e:["Règle le siège pour que les poignées soient à hauteur du milieu de la poitrine.","Le coussin bloque le buste : le balancement, triche la plus courante en rowing, devient impossible.","Tire les poignées vers toi en amenant les coudes le long des côtes.","Serre les omoplates en fin de traction, une seconde complète.","Reviens lentement bras tendus, en laissant les omoplates s'écarter."],v:["Ne décolle pas la poitrine du coussin, c'est tout l'intérêt de cette machine.","Initie le mouvement par les omoplates, pas par les bras.","Les épaules restent basses, loin des oreilles."],r:"Souffle en tirant, inspire au retour."},
  d24:{d:"Debout face à une poulie haute, barre tenue à deux mains bras tendus, buste légèrement penché vers l'avant.",e:["Recule d'un pas et penche le buste d'environ vingt degrés.","Garde les bras tendus, coudes très légèrement fléchis et fixes.","Abaisse la barre en arc de cercle jusqu'aux cuisses, sans plier les coudes.","Ce mouvement isole le grand dorsal sans faire intervenir les biceps, chose rare.","Remonte lentement en résistant, jusqu'à sentir l'étirement du dos."],v:["Si tu plies les coudes, ce n'est plus un pull-over mais une extension triceps.","Le buste reste immobile, ne te redresse pas pour aider.","Charge modérée : l'exercice se joue sur la contraction, pas sur le poids."],r:"Souffle en abaissant, inspire en remontant."},
  d25:{d:"Assis à la machine, pieds calés, barre large tenue en pronation, buste droit.",e:["Prends la barre nettement plus large que les épaules, paumes vers le bas.","Redresse le buste et sors la poitrine.","Tire la barre vers le haut de l'abdomen en écartant les coudes vers l'extérieur.","Cette prise cible le haut du dos et les trapèzes plutôt que le grand dorsal.","Reviens lentement bras tendus sans laisser le dos s'arrondir."],v:["Le balancement du buste d'avant en arrière annule tout le travail du dos.","Les épaules ne remontent pas vers les oreilles en fin de traction.","Garde les genoux légèrement fléchis."],r:"Souffle en tirant, inspire au retour."},
  d26:{d:"Debout dans la machine, poignées tenues le long du corps, bras tendus, épaules relâchées.",e:["Garde les bras complètement tendus : ils ne servent qu'à porter la charge.","Hausse les épaules vers les oreilles, le plus haut possible.","Marque une contraction d'une seconde en position haute.","Redescends lentement en laissant les épaules s'étirer vers le bas.","Le mouvement reste strictement vertical."],v:["Ne fais jamais de rotation des épaules sous charge, l'articulation le supporte mal.","Ne plie pas les coudes, cela transformerait l'exercice en tirage.","Le cou reste détendu."],r:"Souffle en montant, inspire en redescendant."},
  d27:{d:"Debout sur les cales, poitrine appuyée sur le coussin incliné, poignées tenues bras tendus.",e:["Règle la hauteur du coussin pour qu'il soutienne la poitrine sans gêner la respiration.","Fléchis légèrement les genoux et plaque la poitrine.","Tire les poignées vers le haut en amenant les coudes vers l'arrière.","Serre les omoplates en fin de traction.","Redescends lentement bras tendus, sans décoller la poitrine."],v:["L'appui poitrine protège les lombaires : ne t'en écarte pas pour tirer plus lourd.","Ne tire pas avec les seuls bras, le mouvement part des omoplates.","Garde la nuque dans l'axe, ne relève pas la tête."],r:"Souffle en tirant, inspire à la descente."},
  d28:{d:"Installé sur le banc à lombaires, bassin sur le coussin, chevilles bloquées, corps aligné.",e:["Règle le coussin juste sous les hanches pour permettre la flexion.","Croise les bras sur la poitrine et garde le dos droit.","Descends le buste lentement, en gardant le dos plat et non arrondi.","Remonte jusqu'à l'alignement du corps, sans jamais aller au-delà.","Marque une brève pause en position alignée."],v:["Monter en hyperextension au-delà de l'alignement est la faute classique de cet exercice.","Ne rebondis pas en bas de course.","Commence sans charge, le poids du buste suffit largement au début."],r:"Souffle en remontant, inspire à la descente."},
  p24:{d:"Assis dans la machine, dos plaqué, avant-bras contre les coussins, coudes à hauteur d'épaules.",e:["Règle le siège pour que les coudes soient exactement à hauteur des épaules.","Ajuste l'écartement de départ pour sentir un étirement confortable, sans forcer.","Rapproche les coussins devant toi en contractant la poitrine.","Marque une contraction d'une seconde en position fermée.","Reviens lentement, en arrêtant l'ouverture avant l'étirement maximal."],v:["Ne force jamais l'ouverture de départ : c'est la position la plus vulnérable pour l'épaule.","Le dos reste plaqué au dossier, ne te penche pas en avant.","Les épaules restent basses pendant tout le mouvement."],r:"Souffle en fermant, inspire à l'ouverture."},
  p25:{d:"Assis dans la machine inclinée, dos plaqué, poignées à hauteur du haut de la poitrine.",e:["Règle le siège pour que les poignées soient au niveau des clavicules.","Plaque le dos et serre légèrement les omoplates contre le dossier.","Pousse les poignées vers l'avant et le haut, sans verrouiller les coudes.","Cette inclinaison cible le haut des pectoraux, souvent en retard.","Reviens lentement jusqu'à ce que les mains arrivent au niveau du buste."],v:["Ne laisse pas les coudes partir loin en arrière au retour.","Le dos ne se décolle pas du dossier pour pousser plus lourd.","Les épaules ne montent pas vers les oreilles."],r:"Souffle en poussant, inspire au retour."},
  p26:{d:"Debout entre deux poulies basses, une poignée dans chaque main le long du corps, un pied en avant.",e:["Avance un pied pour stabiliser la position et penche légèrement le buste.","Garde les coudes légèrement fléchis et fixes pendant tout le mouvement.","Ramène les mains devant toi et vers le haut, en arc de cercle.","Croise légèrement les poignets à hauteur de poitrine pour accentuer la contraction.","Reviens lentement en laissant les pectoraux s'étirer."],v:["La trajectoire montante cible le haut des pectoraux : ne ramène pas les mains à hauteur du bassin.","Si tu plies et tends les coudes, ce devient un développé.","Charge modérée, la position d'étirement sollicite l'épaule."],r:"Souffle en ramenant, inspire à l'ouverture."},
  p27:{d:"Allongé sur un banc plat sous la barre guidée, barre à hauteur du milieu de la poitrine.",e:["Positionne le banc pour que la barre descende sur le milieu des pectoraux, jamais sur le cou.","Plaque le bas du dos et serre les omoplates contre le banc.","Déverrouille la barre et descends en contrôlant jusqu'à effleurer la poitrine.","La trajectoire étant guidée, tu peux pousser sans partenaire de sécurité.","Repousse en tendant les bras, sans verrouiller brutalement les coudes."],v:["Vérifie toujours la position des crochets avant de charger.","Ne fais jamais rebondir la barre sur la poitrine.","Les pieds restent à plat au sol pendant toute la série."],r:"Inspire en descendant, souffle en poussant."},
  p28:{d:"Assis ou allongé dans la machine déclinée, dos plaqué, poignées à hauteur du bas de la poitrine.",e:["Règle le siège pour que les poignées soient au niveau du bas des pectoraux.","Plaque le dos et garde les omoplates serrées.","Pousse les poignées vers l'avant et légèrement vers le bas.","Cet angle cible la partie basse des pectoraux.","Reviens lentement jusqu'au niveau du buste."],v:["Si tu ressens des vertiges en position déclinée, arrête et privilégie une autre variante.","Le dos reste plaqué, sans décollement.","Ne verrouille pas les coudes en fin de poussée."],r:"Souffle en poussant, inspire au retour."},
  p29:{d:"Debout entre deux poulies hautes, une poignée dans chaque main bras écartés en croix, un pied en avant.",e:["Avance un pied et penche le buste d'environ vingt degrés vers l'avant.","Garde les coudes légèrement fléchis, à angle constant.","Ramène les mains devant toi et vers le bas, en arc de cercle.","Croise les poignets devant le bassin pour accentuer la contraction.","Reviens lentement en contrôlant l'ouverture."],v:["La trajectoire descendante cible le bas et le milieu des pectoraux.","Le buste reste immobile, ne te redresse pas pour aider.","N'ouvre pas les bras au-delà du plan du buste."],r:"Souffle en ramenant, inspire à l'ouverture."},
  e23:{d:"Assis dans la machine, dos plaqué, avant-bras contre les coussins latéraux, coudes fléchis.",e:["Règle le siège pour que l'axe de rotation soit aligné avec tes épaules.","Cale les avant-bras contre les coussins, coudes légèrement en avant du buste.","Monte les coudes sur les côtés jusqu'à hauteur d'épaules.","La machine impose la trajectoire : impossible de tricher par balancement.","Redescends lentement en résistant à la charge."],v:["Ne monte pas au-dessus des épaules, le trapèze prendrait le relais.","Les épaules restent basses malgré la brûlure.","Pousse avec les coudes, pas avec les mains."],r:"Souffle en montant, inspire en redescendant."},
  e24:{d:"Debout de profil par rapport à une poulie basse, poignée tenue dans la main extérieure, bras le long du corps.",e:["Passe le câble devant tes cuisses pour que la tension soit maximale dès le départ.","Contrairement aux haltères, la poulie garde une résistance constante sur toute l'amplitude.","Monte le bras sur le côté, coude légèrement fléchi, jusqu'à hauteur d'épaule.","Marque une brève pause en position haute.","Redescends lentement, puis termine toutes les répétitions avant de changer de côté."],v:["Le buste reste strictement immobile, sans inclinaison pour aider.","Ne monte pas au-dessus de l'horizontale.","Charge légère : ce muscle est petit et se blesse facilement."],r:"Souffle en montant, inspire en redescendant."},
  e25:{d:"Assis face au dossier de la machine à écartés, poitrine calée, poignées tenues devant toi bras tendus.",e:["Retourne-toi face au dossier : c'est la même machine que le butterfly, utilisée à l'envers.","Cale la poitrine contre le coussin et garde les bras tendus, coudes à peine fléchis.","Écarte les bras vers l'arrière en menant par les coudes.","Serre les omoplates en fin de mouvement, une seconde complète.","Reviens lentement sans laisser la charge revenir d'un coup."],v:["Ne décolle pas la poitrine du coussin, c'est ce qui empêche de tricher.","Charge très légère : le faisceau postérieur est souvent le plus faible des trois.","Ne tire pas les coudes vers les hanches, ce serait un rowing."],r:"Souffle en écartant, inspire au retour."},
  e26:{d:"Assis sur un banc à dossier vertical sous la barre guidée, barre à hauteur du menton.",e:["Règle le banc pour que la barre descende au niveau du menton, jamais derrière la nuque.","Plaque le dos au dossier et contracte le ventre pour éviter de cambrer.","Déverrouille la barre et pousse vers le haut sans bloquer les coudes.","La trajectoire guidée permet de charger sans craindre le déséquilibre.","Redescends jusqu'au niveau du menton, en contrôlant."],v:["Ne descends jamais la barre derrière la nuque, la position est risquée pour l'épaule.","Si tu cambres pour pousser, la charge est trop lourde.","Vérifie les crochets de sécurité avant chaque série."],r:"Souffle en poussant, inspire en redescendant."},
  e27:{d:"Debout dos à une poulie basse, barre ou poignée tenue à deux mains devant les cuisses, câble passant entre les jambes.",e:["Avance d'un pas pour mettre le câble en tension dès le départ.","Contracte le ventre pour empêcher le buste de basculer en arrière.","Monte les bras tendus devant toi jusqu'à hauteur d'épaules.","Marque une brève pause à l'horizontale, pas plus haut.","Redescends lentement en résistant à la traction."],v:["Le balancement du buste pour lancer la charge annule le travail du deltoïde.","Ne monte pas au-dessus de l'horizontale.","Les épaules restent basses, loin des oreilles."],r:"Souffle en montant, inspire en redescendant."},
  e28:{d:"Debout face à une poulie basse, barre tenue à deux mains en pronation, mains écartées de la largeur des épaules.",e:["Prends la barre largeur d'épaules : une prise serrée contraint l'épaule inutilement.","Redresse le buste et garde les bras tendus au départ.","Tire la barre vers le haut en menant par les coudes, qui montent sur les côtés.","Arrête-toi quand les coudes atteignent la hauteur des épaules, pas au-dessus.","Redescends lentement en contrôlant."],v:["Monter les coudes plus haut que les épaules pince l'articulation : c'est la limite à ne jamais franchir.","Si tu ressens un pincement, abandonne cet exercice au profit des élévations latérales.","Le buste reste immobile."],r:"Souffle en tirant, inspire en redescendant."},
  e29:{d:"Debout de profil par rapport à une poulie réglée à hauteur de coude, poignée dans la main extérieure, coude collé aux côtes à 90°.",e:["Cale une serviette roulée entre le coude et les côtes pour maintenir la position.","Le coude ne quitte jamais ce contact pendant tout le mouvement.","Fais pivoter l'avant-bras vers l'extérieur, en gardant l'angle du coude à 90°.","Va jusqu'à l'amplitude confortable, sans forcer.","Reviens lentement, puis change de côté."],v:["Le coude qui se décolle transfère le travail sur les épaules et le dos.","Mouvement de santé articulaire : privilégie l'amplitude et le contrôle, jamais la charge.","Charge très légère, quelques kilos suffisent."],r:"Souffle en tournant vers l'extérieur, inspire au retour."},
  b24:{d:"Debout face à une poulie basse, barre tenue à deux mains en supination, coudes collés aux côtes.",e:["Recule d'un pas pour mettre le câble en tension dès la position basse.","Verrouille les coudes contre les côtes : ils ne bougent plus.","Monte la barre en fléchissant les coudes, sans bouger les épaules.","La poulie maintient une tension constante, même en bas de mouvement.","Redescends lentement jusqu'à l'extension presque complète."],v:["Le balancement du buste pour lancer la charge est la triche la plus courante.","Les coudes qui avancent transforment le mouvement en soulevé d'épaules.","Ne relâche pas complètement en bas, garde la tension."],r:"Souffle en montant, inspire en redescendant."},
  b25:{d:"Debout face à une poulie basse, corde tenue à deux mains en prise neutre, pouces vers le haut.",e:["Tiens la corde par ses extrémités, paumes se faisant face.","Colle les coudes aux côtes et garde-les fixes.","Monte les mains vers les épaules en gardant la prise neutre.","Cette prise cible le brachial et l'avant-bras plutôt que le biceps seul.","Redescends lentement en contrôlant."],v:["Ne tourne pas les poignets pendant la montée, la prise reste neutre du début à la fin.","Les coudes ne quittent pas les côtes.","Le buste reste immobile."],r:"Souffle en montant, inspire en redescendant."},
  b26:{d:"Debout face à une poulie haute, corde tenue à deux mains, coudes fléchis et collés aux côtes.",e:["Colle les coudes aux côtes : ils constituent le seul point fixe du mouvement.","Tends les avant-bras vers le bas jusqu'à l'extension complète.","En fin de mouvement, écarte les deux brins de la corde pour accentuer la contraction.","Marque une pause d'une seconde, triceps serrés.","Remonte lentement jusqu'à ce que les avant-bras soient à l'horizontale."],v:["Les coudes qui s'éloignent des côtes transfèrent le travail sur le dos.","Ne te penche pas en avant pour pousser avec le poids du corps.","L'écartement final de la corde est ce qui distingue cette variante de la barre."],r:"Souffle en tendant, inspire en remontant."},
  b27:{d:"Debout face à une poulie haute, barre courte tenue en supination, paumes vers le haut, coudes aux côtes.",e:["Prends la barre paumes vers le haut, mains à la largeur des hanches.","Colle les coudes aux côtes et garde-les strictement fixes.","Tends les avant-bras vers le bas jusqu'à l'extension complète.","Cette prise inhabituelle cible davantage le chef latéral du triceps.","Remonte lentement en gardant la tension."],v:["Charge nettement plus légère qu'en prise classique : la position du poignet est moins favorable.","Arrête si le poignet devient douloureux.","Les coudes ne s'écartent pas."],r:"Souffle en tendant, inspire en remontant."},
  b28:{d:"Allongé sur un banc placé devant une poulie basse, barre tenue à deux mains au-dessus du front, coudes fléchis.",e:["Positionne le banc pour que le câble tire dans l'axe des bras.","Garde les coudes pointés vers le plafond et près l'un de l'autre.","Tends les bras vers le haut sans bouger la position des coudes.","Le câble maintient la tension même en fin d'extension, contrairement aux haltères.","Redescends lentement jusqu'au niveau du front."],v:["Les coudes qui s'écartent sont le défaut principal, ils déplacent le travail hors du triceps.","Ne descends pas la barre derrière la tête, cela sollicite l'épaule.","Charge modérée pour garder les coudes stables."],r:"Souffle en tendant, inspire en redescendant."},
  b29:{d:"Genoux ou pieds posés sur la plateforme d'assistance, mains sur les barres parallèles, bras tendus.",e:["Règle l'assistance : plus le contrepoids est lourd, plus l'exercice est facile.","Garde le buste très légèrement incliné vers l'avant et les épaules basses.","Descends en fléchissant les coudes vers l'arrière, jusqu'à l'angle droit.","Diminue l'assistance au fil des semaines pour progresser vers les dips libres.","Repousse en tendant les bras, sans verrouiller."],v:["Ne descends pas plus bas que 90°, l'épaule y devient vulnérable.","Si les épaules remontent vers les oreilles, augmente l'assistance.","Les coudes restent serrés, ils ne partent pas sur les côtés."],r:"Inspire en descendant, souffle en repoussant."},
  b30:{d:"Debout face à une poulie haute, une poignée tenue d'une main en supination, coude collé aux côtes.",e:["Prends la poignée paume vers le haut et colle le coude contre les côtes.","Maintiens le coude avec la main libre si tu as tendance à le laisser bouger.","Tends l'avant-bras vers le bas jusqu'à l'extension complète.","Travailler un bras à la fois révèle les déséquilibres entre les deux côtés.","Remonte lentement, puis change de bras."],v:["Le coude qui se décolle annule le travail : c'est le point à surveiller en priorité.","Ne te penche pas du côté travaillé.","Commence par le bras le plus faible et aligne l'autre sur lui."],r:"Souffle en tendant, inspire en remontant."},
  b31:{d:"Assis sur un banc incliné à 45° placé devant une poulie basse, bras pendant vers l'arrière, poignée en main.",e:["Règle le banc à 45° et laisse le bras pendre naturellement vers l'arrière.","Cette position d'étirement de départ est ce qui rend l'exercice si efficace.","Monte la poignée en fléchissant le coude, sans avancer le bras.","Marque une contraction d'une seconde en haut.","Redescends lentement jusqu'à l'étirement complet."],v:["Ne laisse pas le coude avancer pendant la montée, il reste derrière le buste.","Charge légère : la position étirée met le biceps en tension maximale.","Le dos reste plaqué au dossier."],r:"Souffle en montant, inspire en redescendant."},
  a28:{d:"Assis dans la machine, jambes bloquées par les coussins, buste calé contre l'appui, mains sur les poignées.",e:["Règle l'amplitude de départ modestement : la rotation lombaire sous charge se force facilement.","Bloque bien le bassin avec les coussins prévus à cet effet.","Pivote le buste sur le côté en gardant le dos droit.","Marque une brève pause en fin de rotation.","Reviens lentement, puis change de côté à la série suivante."],v:["Ne charge jamais lourd sur cette machine : la colonne supporte mal la rotation sous contrainte.","Le mouvement est lent et contrôlé, jamais lancé.","Arrête immédiatement en cas de gêne lombaire."],r:"Souffle pendant la rotation, inspire au retour."},
  a29:{d:"Avant-bras posés sur les coussins de la chaise romaine, dos plaqué au dossier, jambes pendantes.",e:["Plaque tout le dos contre le dossier avant de commencer.","Rentre légèrement le bassin pour supprimer la cambrure lombaire.","Monte les genoux vers la poitrine en enroulant le bassin vers le haut.","C'est l'enroulement du bassin qui fait travailler les abdominaux, pas la montée des cuisses.","Redescends lentement sans laisser les jambes tomber."],v:["Si tu te contentes de monter les genoux sans enrouler le bassin, ce sont les fléchisseurs de hanche qui travaillent.","Ne balance pas le corps pour lancer le mouvement.","Tends les jambes pour durcir, fléchis-les pour alléger."],r:"Souffle en montant, inspire en redescendant."},
  a30:{d:"Debout de profil par rapport à une poulie haute, poignée tenue à deux mains bras tendus au-dessus de l'épaule.",e:["Écarte les pieds pour une base stable et fléchis légèrement les genoux.","Garde les bras tendus : ils forment un levier rigide.","Tire les mains en diagonale vers la hanche opposée, comme un coup de hache.","La rotation vient du tronc et du bassin, pas des bras.","Reviens lentement en résistant, puis change de côté."],v:["Si tu plies les bras, ce devient un tirage et les obliques ne travaillent plus.","Les genoux restent souples, ne verrouille pas les jambes.","Mouvement contrôlé, jamais lancé en force."],r:"Souffle pendant la rotation, inspire au retour."},
  a31:{d:"Debout de profil par rapport à une poulie réglée à hauteur de poitrine, les deux mains jointes sur la poignée contre le sternum.",e:["Écarte-toi du montant jusqu'à sentir une tension franche.","Écarte les pieds et contracte le ventre pour verrouiller le tronc.","Tends les bras devant toi, à l'horizontale.","Toute la difficulté consiste à ne pas laisser la poulie te faire pivoter.","Reviens lentement à la poitrine, puis change de côté."],v:["Si le buste tourne, réduis la charge : l'objectif est l'immobilité, pas la poussée.","Les hanches restent face à l'avant, elles ne suivent pas les bras.","Travail du gainage anti-rotation, rarement sollicité autrement."],r:"Respire régulièrement sans bloquer, malgré la tension."},
  a32:{d:"Allongé sur un banc incliné, mains agrippées derrière la tête au support, genoux fléchis et décollés.",e:["Agrippe fermement le support derrière ta tête pour stabiliser le haut du corps.","Plaque le bas du dos contre le banc.","Ramène les genoux vers la poitrine en enroulant le bassin vers le haut.","L'inclinaison du banc augmente la difficulté par rapport au sol.","Redescends lentement sans poser les pieds."],v:["Le bas du dos reste plaqué : s'il se creuse, réduis l'inclinaison.","Ne donne pas d'élan avec les jambes.","Commence avec une inclinaison faible et augmente progressivement."],r:"Souffle en ramenant les genoux, inspire en redescendant."},
  a33:{d:"Debout de profil par rapport à une poulie basse, poignée tenue dans la main extérieure le long du corps, main libre sur la nuque.",e:["Écarte-toi du montant pour mettre le câble en tension.","Garde le buste dans le plan latéral : ni rotation, ni inclinaison vers l'avant.","Fléchis le buste du côté opposé à la poulie, contre la résistance.","Reviens en contractant l'oblique du côté chargé.","Termine toutes les répétitions avant de changer de côté."],v:["Ne te penche pas en avant, le mouvement est strictement latéral.","Charge modérée : les obliques répondent au contrôle plutôt qu'au poids.","Les hanches restent immobiles."],r:"Souffle en revenant, inspire en fléchissant."},
  c24:{d:"Assis dans le vélo à dossier, dos calé, pieds sanglés sur les pédales devant toi.",e:["Règle le siège pour que la jambe soit presque tendue en fin de poussée, sans être verrouillée.","Commence par trois minutes à faible résistance pour échauffer les genoux.","Installe une cadence régulière que tu peux tenir sans t'essouffler complètement.","Le dossier soulage entièrement le bas du dos : c'est l'option la plus douce du parc cardio.","Termine par deux minutes à faible résistance."],v:["Ne verrouille jamais les genoux en fin de poussée.","Le dos reste en contact avec le dossier, ne te penche pas en avant.","Bonne option en cas de sensibilité lombaire ou de reprise après une pause."],r:"Respire profondément et régulièrement."},
  c25:{d:"Debout sur les marches, mains posées légèrement sur les rampes, buste droit.",e:["Pose tout le pied sur chaque marche, pas seulement la pointe.","Garde le buste droit et le regard devant : ne te penche pas sur les rampes.","Commence lentement pendant deux minutes pour trouver le rythme.","S'appuyer sur les rampes allège le corps et fausse totalement la dépense.","Termine par deux minutes de rythme lent."],v:["Ne t'agrippe pas aux rampes : elles servent à l'équilibre, pas au soutien.","Exercice exigeant pour les genoux : évite-le en cas de gêne rotulienne.","Ne saute pas de marches, la montée reste régulière."],r:"Respire profondément et régulièrement."},
  c26:{d:"Assis sur le rameur, pieds sanglés, poignée tenue à deux mains, genoux fléchis et buste légèrement penché vers l'avant.",e:["Retiens l'ordre : jambes, buste, bras. C'est la règle qui fait toute la différence.","Pousse d'abord avec les jambes jusqu'à les tendre presque complètement.","Bascule ensuite le buste légèrement vers l'arrière.","Tire enfin la poignée vers le bas des côtes, coudes le long du corps.","Reviens dans l'ordre inverse : bras, buste, jambes."],v:["Tirer d'abord avec les bras est l'erreur classique : les jambes fournissent l'essentiel de la puissance.","Le dos ne s'arrondit jamais, même en fin de série.","Ne tire pas la poignée jusqu'au menton, elle s'arrête au bas des côtes."],r:"Souffle pendant la poussée, inspire pendant le retour."},
  c27:{d:"Assis sur le vélo à air, mains sur les poignées mobiles, pieds sur les pédales.",e:["Règle la selle comme sur un vélo classique : jambe presque tendue en bas de course.","Pousse et tire alternativement avec les bras pendant que les jambes pédalent.","La résistance augmente avec ta propre vitesse : c'est toi qui fixes l'intensité.","Commence deux minutes lentement, cette machine essouffle très vite.","Termine par deux minutes de pédalage souple."],v:["Ne pars pas trop fort : l'autorégulation de la résistance rend cette machine impitoyable.","Le dos reste droit, ne t'affaisse pas sur les poignées.","Arrête-toi si tu ne peux plus tenir une phrase complète."],r:"Respire de façon rythmée et continue."},
  c28:{d:"Debout face à la machine, poignées tenues à deux mains au-dessus de la tête, pieds écartés de la largeur des hanches.",e:["Attrape les poignées bras tendus au-dessus de la tête.","Tire vers le bas en fléchissant les hanches et les genoux simultanément.","Termine le mouvement bras le long des cuisses, buste penché vers l'avant.","La puissance vient de la charnière de hanche, pas des seuls bras.","Remonte en tendant les jambes et en levant les bras."],v:["Ne tire pas uniquement avec les bras, ils s'épuiseraient en quelques répétitions.","Le dos reste droit pendant la flexion, jamais arrondi.","Garde les genoux souples à chaque cycle."],r:"Souffle pendant la traction, inspire pendant la remontée."}
};

